// Geschiedenissen (ot-2). Zie docs/BIJBELREIS.md, "De 150 geschiedenissen".
// Nummers 32–64 (Leviticus t/m 2 Koningen 5). Controle tegen de Statenvertaling: scripts/bijbel-controle/ot-2.txt.
BR.geschiedenissen = BR.geschiedenissen || [];
BR.kernwoorden = BR.kernwoorden || {};

BR.geschiedenissen.push(
{ nr: 32, t: "De Grote Verzoendag", ref: "Leviticus 8–10; 16", sectie: "woestijn",
  stappen: ["leviticus:verzoendag:0", "leviticus:verzoendag:1", "leviticus:verzoendag:2", "leviticus:verzoendag:3", "leviticus:verzoendag:4"],
  vorm: "plek",
  uitleg: "Bij de berg Sinaï wijdt Mozes Aäron en zijn zonen tot priesters. Hij wast hen, doet hun de priesterkleren aan en zalft Aäron met olie. Op de achtste dag brengt Aäron de eerste offers, en vuur van de HEERE verteert het offer op het altaar. Maar Nadab en Abihu brengen vreemd vuur, dat God hun niet geboden had. Vuur van de HEERE verteert hen, en ze sterven. Daarna geeft God de regels voor één dag in het jaar: de Grote Verzoendag. Dan gaat de hogepriester achter het voorhangsel en sprenkelt hij bloed op het verzoendeksel. Op de kop van een tweede bok belijdt hij alle zonden van het volk, en die bok wordt de woestijn in gebracht.",
  betekenis: "God is heilig: wie bij Hem komt, moet komen op de manier die Hij zegt (Leviticus 10:3). Het bloed van de offers deed verzoening (Leviticus 17:11). Maar het wees vooruit naar de Heere Jezus: Hij ging niet met bloed van bokken, maar met Zijn eigen bloed eenmaal het heiligdom in (Hebreeën 9:11–12).",
  wie: ["Aäron", "Mozes", "Nadab", "Abihu", "Eleazar", "Ithamar"],
  kw: "offeren",
  ontdek: { soort: "verbanden", titel: "Van de Verzoendag naar de Heere Jezus: wat zegt de Hebreeënbrief?", items: [
    ["Leviticus 16:34", "Eenmaal per jaar doet de hogepriester verzoening voor al de zonden van Israël.", "Hebreeën 9:25–26", "Christus hoefde Zich niet elk jaar te offeren: Hij is eenmaal verschenen om de zonde weg te doen door Zijn eigen offer."],
    ["Leviticus 16:14–15", "De hogepriester gaat met het bloed van een stier en een bok achter het voorhangsel.", "Hebreeën 9:12", "Christus ging niet met bloed van bokken en kalveren, maar met Zijn eigen bloed het heiligdom in."],
    ["Leviticus 16:2", "Niemand mag zomaar achter het voorhangsel komen.", "Hebreeën 10:19–20", "Door het bloed van Jezus is er een nieuwe en levende weg ‘door het voorhangsel, dat is, door Zijn vlees’."],
    ["Leviticus 9:7", "Aäron moet eerst offeren voor zijn eigen zonden.", "Hebreeën 7:26–27", "De Heere Jezus is heilig en zonder zonde; Hij hoefde niet eerst voor Zichzelf te offeren."]] },
  quiz: [{ q: "Over hoeveel bokken wierp Aäron het lot?", a: ["Twee", "Eén", "Zeven"], why: "Leviticus 16:7–8" },
    { q: "Wanneer moest de Grote Verzoendag gehouden worden?", a: ["In de zevende maand, op de tiende dag", "In de eerste maand, op de veertiende dag", "Op elke sabbat"], why: "Leviticus 16:29" },
    { q: "Wie vertelde Aäron wat de HEERE gezegd had, na de dood van Nadab en Abihu?", a: ["Mozes", "Eleazar", "Jozua"], why: "Leviticus 10:3" },
    { q: "Wat moest de rook van het reukwerk bedekken?", a: ["Het verzoendeksel", "Het brandofferaltaar", "De ingang van de tent"], why: "Leviticus 16:13" }],
  cross: [["Hebreeën 9:7", "In het heilige der heiligen ging alleen de hogepriester, eenmaal per jaar, ‘niet zonder bloed’."],
    ["Hebreeën 9:11–12", "Christus is met Zijn eigen bloed eenmaal ingegaan in het heiligdom en heeft een eeuwige verlossing gebracht."],
    ["Hebreeën 10:10", "Wij zijn geheiligd ‘door de offerande des lichaams van Jezus Christus, eenmaal geschied’."]],
  tl: [-1445, -1445], tijd: "ca. 1445 v.Chr.",
  tijdNoot: "Reconstructie: in het tweede jaar na de uittocht, kort nadat de tabernakel was opgericht (Exodus 40:17; Numeri 1:1). De uittocht wordt op grond van 1 Koningen 6:1 rond 1446 v.Chr. gedateerd. Wanneer de Grote Verzoendag voor het eerst gehouden werd, staat niet in de Bijbel. Wie de uittocht in de 13e eeuw v.Chr. dateert, komt bijna twee eeuwen later uit." },

{ nr: 33, t: "Twaalf verspieders in Kanaän", ref: "Numeri 13–14", sectie: "woestijn",
  stappen: ["numeri:woestijn:3", "numeri:woestijn:4"],
  vorm: "route",
  uitleg: "Vanuit de woestijn Paran stuurt Mozes op Gods bevel twaalf mannen het land Kanaän in, uit elke stam één. Veertig dagen lang verkennen ze het land, van het zuiden tot ver in het noorden. Uit het dal Eskol nemen ze een druiventros mee, die ze met z’n tweeën aan een draagstok dragen. Terug in Kades zeggen tien van hen: het land is goed, maar het volk is sterk en we zagen reuzen. ‘wij waren als sprinkhanen in onze ogen.’ Kaleb en Jozua zeggen: de HEERE is met ons, wees niet bang. Maar het volk huilt de hele nacht en wil de twee zelfs stenigen. Dan zegt God: veertig jaar zullen jullie in de woestijn blijven, een jaar voor elke dag. Iedereen van twintig jaar en ouder zal daar sterven, behalve Kaleb en Jozua.",
  betekenis: "Het volk zag de reuzen groter dan God, en geloofde Zijn belofte niet: ‘zij hebben niet kunnen ingaan vanwege hun ongeloof’ (Hebreeën 3:19). Over Kaleb zegt God dat hij volhard heeft Hem na te volgen (Numeri 14:24).",
  wie: ["Mozes", "Jozua", "Kaleb"],
  ontdek: { soort: "kaart", vraag: "Tik op Kades, waar de verspieders na veertig dagen terugkwamen bij Mozes en het volk.", id: "kadesbarnea", v: [[29.0, 33.0], [32.5, 36.5]] },
  quiz: [{ q: "Hoeveel mannen stuurde Mozes het land in?", a: ["Twaalf, uit elke stam één", "Twee", "Zeventig"], why: "Numeri 13:2" },
    { q: "Hoe lang verkenden ze het land?", a: ["40 dagen", "7 dagen", "40 jaar"], why: "Numeri 13:25" },
    { q: "Wie zei: ‘Laat ons vrijmoedig optrekken’?", a: ["Kaleb", "Mozes", "Aäron"], why: "Numeri 13:30" },
    { q: "Hoe droegen ze de druiventros uit het dal Eskol?", a: ["Met z’n tweeën aan een draagstok", "Op een ezel", "In een mand op het hoofd"], why: "Numeri 13:23" },
    { q: "Wie van de volwassenen mochten later het land in?", a: ["Kaleb en Jozua", "Mozes en Aäron", "Alle twaalf verspieders"], why: "Numeri 14:30" }],
  cross: [["Hebreeën 3:17–19", "Wie in de woestijn stierven, konden niet ingaan ‘vanwege hun ongeloof’."],
    ["Psalm 95:10–11", "‘Veertig jaren heb Ik verdriet gehad aan dit geslacht.’"],
    ["Jozua 14:6–12", "Vijfenveertig jaar later vraagt Kaleb het bergland bij Hebron, waar hij als verspieder geweest was."]],
  tl: [-1445, -1445], tijd: "ca. 1445 v.Chr.",
  tijdNoot: "Reconstructie: in het tweede jaar na de uittocht (Numeri 10:11), ‘in de dagen der eerste vruchten van de wijndruiven’ (Numeri 13:20). De uittocht wordt op grond van 1 Koningen 6:1 rond 1446 v.Chr. gedateerd; wie hem in de 13e eeuw v.Chr. plaatst, komt bijna twee eeuwen later uit." },

{ nr: 34, t: "De koperen slang", ref: "Numeri 20–21", sectie: "woestijn",
  stappen: ["numeri:woestijn:5", "numeri:woestijn:6", "numeri:woestijn:7", "numeri:woestijn:8", "numeri:woestijn:9"],
  vorm: "route",
  uitleg: "Het volk is na veertig jaar weer in Kades. Mirjam sterft, en er is geen water. God zegt tegen Mozes: spreek tegen de rots. Maar Mozes slaat er twee keer op. Dan zegt God dat Mozes en Aäron het volk niet in het land zullen brengen, omdat ze Hem niet geloofd hebben. Edom laat Israël niet door zijn land trekken, en op de berg Hor sterft Aäron. Op de lange omweg om Edom heen wordt het volk moedeloos. Het spreekt tegen God en Mozes: ‘onze ziel walgt over dit zeer lichte brood.’ Dan stuurt de HEERE vurige slangen, en veel mensen sterven. Het volk zegt: ‘Wij hebben gezondigd.’ Dan zegt God tegen Mozes: maak een slang en zet die op een paal. Wie gebeten is en naar de koperen slang kijkt, blijft leven.",
  betekenis: "God gaf geen medicijn, maar een belofte: wie kijkt, zal leven (Numeri 21:8). De Heere Jezus zegt dat Hij zo verhoogd moest worden, ‘opdat een iegelijk, die in Hem gelooft, niet verderve, maar het eeuwige leven hebbe’ (Johannes 3:14–15).",
  wie: ["Mozes", "Aäron", "Mirjam", "Eleazar"],
  kw: "leven",
  ontdek: { soort: "verbanden", titel: "De woestijn en de Heere Jezus: welke verbanden legt het Nieuwe Testament?", items: [
    ["Numeri 21:8–9", "Wie gebeten is en naar de koperen slang kijkt, blijft leven.", "Johannes 3:14–15", "Wie gelooft in de Zoon des mensen, Die verhoogd is, heeft het eeuwige leven."],
    ["Numeri 21:5", "Het volk walgt van het manna, het brood uit de hemel.", "Johannes 6:32–35", "De Heere Jezus zegt: ‘Ik ben het Brood des levens.’"],
    ["Numeri 20:11", "Uit de rots komt water voor het hele volk.", "1 Korinthe 10:4", "Paulus schrijft: ‘de steenrots was Christus’."]] },
  quiz: [{ q: "Wat moest Mozes volgens God doen bij de rots in Kades?", a: ["Tegen de rots spreken", "Twee keer op de rots slaan", "Een put graven"], why: "Numeri 20:8" },
    { q: "Op welke berg stierf Aäron?", a: ["De berg Hor", "De berg Nebo", "De berg Sinaï"], why: "Numeri 20:28" },
    { q: "Waarvan zei het volk dat het ervan walgde?", a: ["Van het lichte brood (het manna)", "Van het water uit de rots", "Van de kwartels"], why: "Numeri 21:5" },
    { q: "Wat moest iemand doen die door een slang gebeten was?", a: ["Naar de koperen slang kijken", "Een offer brengen", "Zich wassen in de rivier"], why: "Numeri 21:8–9" },
    { q: "Wat deed koning Hizkia eeuwen later met de koperen slang?", a: ["Hij verbrijzelde hem, omdat het volk ervoor rookte", "Hij zette hem in de tempel", "Hij gaf hem aan de koning van Babel"], why: "2 Koningen 18:4" }],
  cross: [["Johannes 3:14–15", "‘Gelijk Mozes de slang in de woestijn verhoogd heeft, alzo moet de Zoon des mensen verhoogd worden.’"],
    ["2 Koningen 18:4", "Later werd de koperen slang een afgod; koning Hizkia sloeg hem stuk en noemde hem Nehustan."],
    ["Deuteronomium 32:51", "Mozes mocht het land niet in, omdat hij God niet geheiligd had bij het twistwater van Kades."]],
  tl: [-1407, -1407], tijd: "ca. 1407 v.Chr.",
  tijdNoot: "Reconstructie: Aäron stierf in het veertigste jaar na de uittocht, op de eerste dag van de vijfde maand (Numeri 33:38). De uittocht wordt op grond van 1 Koningen 6:1 rond 1446 v.Chr. gedateerd; wie hem in de 13e eeuw v.Chr. plaatst, komt bijna twee eeuwen later uit." },

{ nr: 35, t: "Bileam en zijn ezelin", ref: "Numeri 22–24", sectie: "woestijn",
  stappen: ["numeri:moab:0"],
  vorm: "route",
  uitleg: "Israël kampeert in de vlakten van Moab, tegenover Jericho. Balak, de koning van Moab, is bang voor dit grote volk. Hij laat Bileam uit Pethor halen om Israël te vervloeken. Maar God zegt tegen Bileam: ‘Gij zult dat volk niet vloeken, want het is gezegend.’ Later mag Bileam toch gaan, als hij alleen zegt wat God hem zegt. Onderweg staat de Engel van de HEERE met een getrokken zwaard op de weg. De ezelin ziet Hem en wijkt drie keer uit. Bileam slaat haar, en dan opent de HEERE de mond van de ezelin. In Moab probeert Balak het drie keer, maar steeds zegent Bileam Israël. Hij spreekt zelfs over een Ster die uit Jakob zal voortkomen.",
  betekenis: "Wie God zegent, kan door niemand vervloekt worden: ‘Wat zal ik vloeken, dien God niet vloekt?’ (Numeri 23:8). God veranderde de vloek in een zegen, ‘omdat de HEERE, uw God, u liefhad’ (Deuteronomium 23:5).",
  wie: ["Bileam", "Balak"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Wat heb ik u gedaan, dat gij mij nu driemaal geslagen hebt?", "De ezelin", ["Balak", "Bileam"]],
    ["Wat zal ik vloeken, dien God niet vloekt?", "Bileam", ["Balak", "Mozes"]],
    ["Ik heb u genomen, om mijn vijanden te vloeken; maar zie, gij hebt hen doorgaans gezegend!", "Balak", ["Bileam", "De Engel van de HEERE"]],
    ["Hoe goed zijn uw tenten, Jakob! uw woningen, Israël!", "Bileam", ["Balak", "Jozua"]]] },
  quiz: [{ q: "Wie was Balak?", a: ["De koning van Moab", "Een profeet uit Israël", "De vader van Bileam"], why: "Numeri 22:4" },
    { q: "Wie zag als eerste de Engel van de HEERE op de weg?", a: ["De ezelin", "Bileam", "De vorsten van Moab"], why: "Numeri 22:23" },
    { q: "Hoe vaak sloeg Bileam zijn ezelin?", a: ["Drie keer", "Eén keer", "Zeven keer"], why: "Numeri 22:28" },
    { q: "Wat deed Bileam telkens als Balak wilde dat hij Israël vervloekte?", a: ["Hij zegende Israël", "Hij vervloekte Israël", "Hij liep weg"], why: "Numeri 24:10" }],
  cross: [["Numeri 24:17", "Bileam ziet ver vooruit: ‘Er zal een ster voortkomen uit Jakob, en er zal een scepter uit Israël opkomen.’"],
    ["Deuteronomium 23:5", "De HEERE wilde niet naar Bileam horen en veranderde de vloek in een zegen."],
    ["2 Petrus 2:15–16", "Bileam ‘heeft het loon der ongerechtigheid liefgehad’; een stom dier, sprekend met mensenstem, hield hem tegen."]],
  tl: [-1407, -1406], tijd: "ca. 1407–1406 v.Chr.",
  tijdNoot: "Reconstructie: na de dood van Aäron in het veertigste jaar (Numeri 33:38) en vóór de toespraken van Mozes in de elfde maand van dat jaar (Deuteronomium 1:3). De uittocht wordt op grond van 1 Koningen 6:1 rond 1446 v.Chr. gedateerd; andere onderzoekers komen bijna twee eeuwen later uit." },

{ nr: 36, t: "Mozes neemt afscheid en sterft", ref: "Deuteronomium 28–34", sectie: "woestijn",
  stappen: ["numeri:moab:3", "numeri:moab:4", "numeri:moab:5"],
  vorm: "plek",
  uitleg: "In de vlakten van Moab houdt Mozes zijn laatste toespraken. Hij zet het volk zegen en vloek voor: zegen als ze naar de stem van de HEERE luisteren, vloek als ze dat niet doen. ‘Het leven en den dood heb ik u voorgesteld … kiest dan het leven.’ Voor de ogen van heel Israël zegt hij tegen Jozua: ‘Wees sterk en heb goeden moed.’ Mozes schrijft de wet op en geeft die aan de priesters, en hij leert het volk een lied. Voor zijn dood zegent hij de stammen van Israël. Dan klimt hij de berg Nebo op, en de HEERE laat hem het hele land zien. Daar sterft Mozes, honderdtwintig jaar oud. God Zelf begraaft hem, en niemand weet waar zijn graf is.",
  betekenis: "Mozes mocht het land niet in, omdat hij God bij het twistwater van Kades niet geheiligd had (Deuteronomium 32:51–52). Toch noemt de Bijbel hem bij zijn dood ‘de knecht des HEEREN’ (Deuteronomium 34:5).",
  wie: ["Mozes", "Jozua"],
  ontdek: { soort: "volgorde", titel: "Wat gebeurde er aan het eind van het leven van Mozes? Zet het in de goede volgorde.", items: ["Mozes houdt zijn toespraken in de vlakten van Moab", "Jozua hoort: wees sterk en heb goeden moed", "Mozes zegent de stammen", "Mozes ziet het land vanaf de Nebo", "Mozes sterft en God begraaft hem"] },
  quiz: [{ q: "Hoe oud was Mozes toen hij stierf?", a: ["120 jaar", "100 jaar", "80 jaar"], why: "Deuteronomium 34:7" },
    { q: "Vanaf welke berg liet de HEERE Mozes het land zien?", a: ["De berg Nebo", "De berg Sinaï", "De berg Karmel"], why: "Deuteronomium 34:1" },
    { q: "Wat zei Mozes over leven en dood?", a: ["Kiest dan het leven", "Niemand kan kiezen", "Kiest wat u wilt"], why: "Deuteronomium 30:19" },
    { q: "Hoe lang beweende Israël Mozes?", a: ["Dertig dagen", "Zeven dagen", "Een jaar"], why: "Deuteronomium 34:8" }],
  cross: [["Deuteronomium 18:15", "Mozes belooft: de HEERE zal een Profeet verwekken zoals ik. Petrus haalt dit aan in zijn prediking over de Heere Jezus (Handelingen 3:22)."],
    ["Hebreeën 3:5", "Mozes was getrouw in Gods hele huis, als een dienaar."],
    ["Mattheüs 17:3", "Eeuwen later spreken Mozes en Elia met de Heere Jezus op de berg."]],
  tl: [-1406, -1406], tijd: "ca. 1406 v.Chr.",
  tijdNoot: "Reconstructie: Mozes sprak in het veertigste jaar, in de elfde maand (Deuteronomium 1:3), en stierf kort daarna. De uittocht wordt op grond van 1 Koningen 6:1 rond 1446 v.Chr. gedateerd; wie hem in de 13e eeuw v.Chr. plaatst, komt bijna twee eeuwen later uit." },

{ nr: 37, t: "Jozua krijgt de leiding; Rachab verbergt de verspieders", ref: "Jozua 1–2", sectie: "kanaan",
  stappen: ["jozua:intocht:0", "jozua:intocht:1"],
  vorm: "route",
  uitleg: "Na de dood van Mozes spreekt de HEERE tot Jozua: trek met het volk over de Jordaan, naar het land dat Ik hun geef. Drie keer zegt God: ‘wees sterk en heb goeden moed’. Vanuit Sittim stuurt Jozua in het geheim twee verspieders naar Jericho. Ze komen in het huis van Rachab, dat op de stadsmuur staat. Als de koning van Jericho hen laat zoeken, verbergt Rachab hen op het dak onder het vlas. Ze zegt: ‘Ik weet, dat de HEERE u dit land gegeven heeft.’ De verspieders beloven dat zij en haar familie gespaard worden, als ze een scharlakenrood koord aan het venster bindt. Ze laat hen aan een touw door het venster zakken. Na drie dagen in het gebergte komen ze terug bij Jozua.",
  betekenis: "Rachab beleed dat de God van Israël ‘een God boven in den hemel, en beneden op de aarde’ is (Jozua 2:11). Daarom noemt Hebreeën 11:31 haar bij de gelovigen: zij ‘is niet omgekomen met de ongehoorzamen’.",
  wie: ["Jozua", "Rachab"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Heb Ik het u niet bevolen? wees sterk en heb goeden moed", "De HEERE", ["Mozes", "Rachab"]],
    ["Breng de mannen uit, die tot u gekomen zijn", "De koning van Jericho", ["Jozua", "Rachab"]],
    ["Ik weet, dat de HEERE u dit land gegeven heeft", "Rachab", ["Jozua", "De koning van Jericho"]],
    ["Zekerlijk, de HEERE heeft dat ganse land in onze handen gegeven", "De twee verspieders", ["Rachab", "De koning van Jericho"]]] },
  quiz: [{ q: "Van welke plaats stuurde Jozua de twee verspieders?", a: ["Sittim", "Gilgal", "Kades"], why: "Jozua 2:1" },
    { q: "Waar verborg Rachab de verspieders?", a: ["Op het dak, onder het vlas", "In een put", "In de stadspoort"], why: "Jozua 2:6" },
    { q: "Wat moest Rachab aan het venster binden?", a: ["Een snoer van scharlakendraad", "Een witte doek", "Een palmtak"], why: "Jozua 2:18" },
    { q: "Hoe lang verborgen de verspieders zich in het gebergte?", a: ["Drie dagen", "Zeven dagen", "Veertig dagen"], why: "Jozua 2:22" }],
  cross: [["Hebreeën 11:31", "‘Door het geloof is Rachab, de hoer, niet omgekomen met de ongehoorzamen.’"],
    ["Jakobus 2:25", "Rachab liet met haar daden zien dat haar geloof echt was."],
    ["Mattheüs 1:5", "Rachab staat in het geslachtsregister van de Heere Jezus, als moeder van Boaz."]],
  tl: [-1406, -1406], tijd: "ca. 1406 v.Chr.",
  tijdNoot: "Reconstructie: veertig jaar na de uittocht (Numeri 14:33–34), die op grond van 1 Koningen 6:1 rond 1446 v.Chr. wordt gedateerd. Wie de uittocht in de 13e eeuw v.Chr. dateert, plaatst de intocht rond 1230–1200 v.Chr." },

{ nr: 38, t: "Door de Jordaan", ref: "Jozua 3–4", sectie: "kanaan",
  stappen: ["jozua:intocht:2", "jozua:intocht:3"],
  vorm: "route",
  uitleg: "Jozua zegt tegen het volk: ‘Heiligt u! want morgen zal de HEERE wonderheden in het midden van ulieden doen.’ De priesters dragen de ark van het verbond voorop, en het volk moet tweeduizend el afstand houden. Het is oogsttijd, en de Jordaan staat tot aan de oevers vol. Zodra de voeten van de priesters in het water komen, blijft het water van boven staan als een hoop. Dat gebeurt heel ver weg, bij de stad Adam. De priesters staan midden in de Jordaan op het droge, tot het hele volk aan de overkant is. Twaalf mannen, uit elke stam één, nemen twaalf stenen mee uit het midden van de rivier. In Gilgal zet Jozua die stenen neer als teken voor later.",
  betekenis: "De stenen waren er voor de kinderen: als die later zouden vragen wat de stenen betekenen, moesten de ouders vertellen wat God gedaan had (Jozua 4:21–22). God deed het, ‘opdat alle volken der aarde de hand des HEEREN kennen zouden, dat zij sterk is’ (Jozua 4:24).",
  wie: ["Jozua", "Priesters"],
  ontdek: { soort: "onthul", titel: "Tik op een getal: wat betekent het?", items: [
    ["2000 el", "Zo veel ruimte moest er zijn tussen het volk en de ark: bijna een kilometer (3:4)."],
    ["12 mannen", "Uit elke stam één, om een steen te dragen (4:2–5)."],
    ["12 stenen", "Uit het midden van de Jordaan meegenomen en in Gilgal opgericht (4:8, 20)."],
    ["40.000", "Ongeveer veertigduizend gewapende krijgsmannen trokken voor de HEERE uit naar de vlakte van Jericho (4:13)."],
    ["De 10e dag", "Op de tiende dag van de eerste maand kwam het volk uit de Jordaan (4:19)."]] },
  quiz: [{ q: "Wat gebeurde er toen de voeten van de priesters het water raakten?", a: ["Het water van boven bleef staan als een hoop", "Het water werd rood als bloed", "Er kwam een sterke oostenwind, zoals bij de Schelfzee"], why: "Jozua 3:15–16" },
    { q: "Hoeveel stenen werden uit de Jordaan meegenomen?", a: ["12", "7", "40"], why: "Jozua 4:8" },
    { q: "Waarom moesten de stenen in Gilgal komen te staan?", a: ["Zodat de kinderen later zouden horen wat God gedaan had", "Om er een muur van te bouwen", "Om er een huis voor Jozua van te maken"], why: "Jozua 4:21–22" },
    { q: "Hoe stond de Jordaan erbij toen ze overstaken?", a: ["Vol, tot aan de oevers, want het was oogsttijd", "Bijna droog, want het was zomer", "Bevroren, want het was winter"], why: "Jozua 3:15" }],
  cross: [["Psalm 114:3", "‘De zee zag het, en vlood; de Jordaan keerde achterwaarts.’"],
    ["Exodus 14:21–22", "Veertig jaar eerder ging het volk op het droge door de Schelfzee; Jozua 4:23 legt dat verband zelf."]],
  tl: [-1406, -1406], tijd: "ca. 1406 v.Chr.",
  tijdNoot: "Reconstructie: op de tiende dag van de eerste maand (Jozua 4:19), veertig jaar na de uittocht, die op grond van 1 Koningen 6:1 rond 1446 v.Chr. wordt gedateerd. Wie de uittocht in de 13e eeuw v.Chr. dateert, plaatst de intocht rond 1230–1200 v.Chr." },

{ nr: 39, t: "De muren van Jericho", ref: "Jozua 5–6", sectie: "kanaan",
  stappen: ["jozua:intocht:3", "jozua:intocht:4"],
  vorm: "plek",
  uitleg: "In Gilgal laat Jozua de mannen besnijden, en het volk viert het Pascha. Een dag later houdt het manna op. Bij Jericho ziet Jozua een Man met een getrokken zwaard: de Vorst van het heir des HEEREN. Jozua valt op zijn gezicht, aanbidt en trekt zijn schoenen uit. God zegt hoe Jericho zal vallen. Zes dagen lang gaan ze één keer om de stad, met de ark en zeven priesters met bazuinen, en het volk zwijgt. Op de zevende dag gaan ze zeven keer om de stad. Dan blazen de priesters, het volk juicht met een groot gejuich, en de muur valt onder zich neer. De stad wordt verwoest, maar Rachab en haar familie blijven leven, omdat zij de verspieders verborgen had.",
  betekenis: "De muren vielen niet door wapens, maar ‘door het geloof … als zij tot zeven dagen toe omringd waren geweest’ (Hebreeën 11:30). Dag na dag liepen ze rond zonder dat er iets gebeurde, tot God deed wat Hij had beloofd.",
  wie: ["Jozua", "Rachab", "Priesters"],
  kw: "volharding",
  ontdek: { soort: "volgorde", titel: "Zet de dagen bij Jericho in de goede volgorde.", items: ["Het manna houdt op", "Jozua ontmoet de Vorst van het heir des HEEREN", "Zes dagen lang één keer om de stad", "Op de zevende dag zeven keer om de stad", "Het volk juicht en de muur valt"] },
  quiz: [{ q: "Wat hield op, de dag nadat het volk van het koren van het land had gegeten?", a: ["Het manna", "De regen", "De wolkkolom"], why: "Jozua 5:12" },
    { q: "Wat moest Jozua uittrekken voor de Vorst van het heir des HEEREN?", a: ["Zijn schoenen", "Zijn mantel", "Zijn helm"], why: "Jozua 5:15" },
    { q: "Hoeveel keer gingen ze op de zevende dag om Jericho?", a: ["Zeven keer", "Eén keer", "Twaalf keer"], why: "Jozua 6:15" },
    { q: "Wat mocht het volk niet doen tijdens het rondgaan, tot Jozua het zei?", a: ["Juichen of een woord zeggen", "Lopen", "Eten"], why: "Jozua 6:10" },
    { q: "Wie bleef met haar familie leven toen Jericho viel?", a: ["Rachab", "Debora", "Mirjam"], why: "Jozua 6:25" }],
  cross: [["Hebreeën 11:30", "‘Door het geloof zijn de muren van Jericho gevallen, als zij tot zeven dagen toe omringd waren geweest.’"],
    ["Exodus 3:5", "Ook Mozes moest bij de braamstruik zijn schoenen uittrekken, want het was heilige grond."],
    ["1 Koningen 16:34", "Jozua had gezegd wat er zou gebeuren met wie Jericho weer opbouwde (Jozua 6:26); in de tijd van Achab kwam het uit."]],
  tl: [-1406, -1406], tijd: "ca. 1406 v.Chr.",
  tijdNoot: "Reconstructie: kort na het Pascha op de veertiende dag van de eerste maand (Jozua 5:10), veertig jaar na de uittocht, die op grond van 1 Koningen 6:1 rond 1446 v.Chr. wordt gedateerd. Wie de uittocht in de 13e eeuw v.Chr. dateert, komt rond 1230–1200 v.Chr. uit." },

{ nr: 40, t: "Achan en de stad Ai", ref: "Jozua 7–8", sectie: "kanaan",
  stappen: ["jozua:intocht:5", "jozua:intocht:6", "jozua:intocht:7"],
  vorm: "plek",
  uitleg: "God had gezegd: van wat in Jericho onder de ban is, mag niemand iets nemen. Maar Achan, uit de stam Juda, neemt het toch. Dan gaan er ongeveer drieduizend man naar het kleine Ai, en ze moeten vluchten; ongeveer zesendertig mannen sterven. Jozua scheurt zijn kleren en ligt tot de avond voor de ark. God zegt: ‘Israël heeft gezondigd.’ Door het lot wordt Achan aangewezen, en hij bekent alles. Een mooie mantel uit Babel, tweehonderd sikkels zilver en een gouden staaf liggen begraven in zijn tent. Achan, zijn kinderen en alles wat hij heeft worden in het dal Achor gestenigd en verbrand. Daarna geeft God Ai in de hand van Jozua, door een hinderlaag achter de stad. Op de berg Ebal leest Jozua de hele wet voor aan het volk.",
  betekenis: "Achan zei: ‘ik zag … en ik kreeg lust daartoe, en ik nam ze’ (Jozua 7:21), precies wat het tiende gebod verbiedt (Exodus 20:17). God noemde het de zonde van heel Israël (Jozua 7:11): wat één man verborg, trof het hele volk.",
  wie: ["Jozua", "Achan"],
  ontdek: { soort: "koppel", titel: "Wat hoort bij elkaar?", paren: [
    ["Babylonische mantel", "begraven in de tent van Achan (7:21)"],
    ["Het lot", "wees stam, geslacht, huis en ten slotte Achan aan (7:16–18)"],
    ["Dal Achor", "‘beroering’: hier werd Achan gestenigd (7:25–26)"],
    ["Hinderlaag", "ongeveer vijfduizend man tussen Bethel en Ai (8:12)"],
    ["Berg Ebal", "altaar van gave stenen; de wet voorgelezen (8:30–35)"]] },
  quiz: [{ q: "Wat nam Achan mee uit Jericho?", a: ["Een mantel, zilver en een gouden staaf", "Een zwaard en een schild", "Een gouden beeld"], why: "Jozua 7:21" },
    { q: "Waar verstopte Achan de buit?", a: ["In de grond, midden in zijn tent", "In een grot buiten het kamp", "Onder de ark van het verbond"], why: "Jozua 7:21" },
    { q: "Hoeveel mannen van Israël sneuvelden bij de eerste aanval op Ai?", a: ["Ongeveer 36", "Ongeveer 3000", "Niemand"], why: "Jozua 7:5" },
    { q: "Hoe nam Israël Ai de tweede keer in?", a: ["Met een hinderlaag achter de stad", "Door om de stad te lopen", "Door een tunnel"], why: "Jozua 8:2" }],
  cross: [["Exodus 20:17", "Het tiende gebod: ‘Gij zult niet begeren … noch iets, dat uws naasten is.’"],
    ["Hosea 2:14", "God belooft dat Hij het dal Achor ooit zal maken ‘tot een deur der hoop’."],
    ["Deuteronomium 27:2–4", "Mozes had geboden om na de Jordaan stenen met de wet op te richten op de berg Ebal."]],
  tl: [-1406, -1406], tijd: "ca. 1406 v.Chr.",
  tijdNoot: "Reconstructie: kort na de val van Jericho, veertig jaar na de uittocht, die op grond van 1 Koningen 6:1 rond 1446 v.Chr. wordt gedateerd. Wie de uittocht in de 13e eeuw v.Chr. dateert, komt rond 1230–1200 v.Chr. uit." },

{ nr: 41, t: "De list van de Gibeonieten en het afscheid van Jozua", ref: "Jozua 9–10; 24", sectie: "kanaan",
  stappen: ["jozua:land:0", "jozua:land:1", "jozua:land:2", "jozua:land:6", "jozua:land:7"],
  vorm: "route",
  uitleg: "De Gibeonieten zijn bang voor Israël en bedenken een list. Ze nemen oude zakken, gescheurde wijnzakken, versleten schoenen en beschimmeld brood mee. Zo komen ze in Gilgal en zeggen: we komen uit een ver land. De mannen van Israël vragen de HEERE niet om raad, en Jozua sluit vrede met hen. Drie dagen later blijkt dat ze vlakbij wonen. Ze mogen blijven leven, maar ze worden houthouwers en waterputters. Dan belegeren vijf koningen van de Amorieten Gibeon. Jozua komt te hulp, en de HEERE laat grote hagelstenen op de vijand vallen. Op het gebed van Jozua staat de zon stil. Jaren later roept Jozua alle stammen bij elkaar in Sichem: ‘kiest u heden, wien gij dienen zult … maar aangaande mij, en mijn huis, wij zullen den HEERE dienen.’ Jozua sterft, honderdtien jaar oud.",
  betekenis: "Israël liet zich bedriegen omdat ze ‘den mond des HEEREN niet vraagden’ (Jozua 9:14). Toch bleef de eed staan, en toen Gibeon werd aangevallen, ‘streed de HEERE voor Israël’ (Jozua 10:14).",
  wie: ["Jozua", "Gibeonieten"],
  ontdek: { soort: "kaart", vraag: "Tik op Gibeon, de stad van de mensen die met oud brood en versleten schoenen kwamen.", id: "gibeon", v: "kanaan" },
  quiz: [{ q: "Waarom hadden de Gibeonieten oud brood en versleten schoenen bij zich?", a: ["Om te doen alsof ze uit een ver land kwamen", "Omdat ze arm waren", "Omdat ze verdwaald waren"], why: "Jozua 9:12–13" },
    { q: "Wat vergaten de mannen van Israël te doen?", a: ["De HEERE om raad vragen", "Het brood proeven", "De Gibeonieten tellen"], why: "Jozua 9:14" },
    { q: "Waarmee doodde de HEERE veel vijanden bij Beth-Horon?", a: ["Met grote hagelstenen", "Met een aardbeving", "Met een overstroming"], why: "Jozua 10:11" },
    { q: "Wat zei Jozua over zichzelf en zijn huis?", a: ["Wij zullen de HEERE dienen", "Wij gaan terug naar Egypte", "Wij bouwen een nieuwe stad"], why: "Jozua 24:15" },
    { q: "Hoe oud werd Jozua?", a: ["110 jaar", "120 jaar", "85 jaar"], why: "Jozua 24:29" }],
  cross: [["2 Samuël 21:1–2", "Saul brak later de eed aan de Gibeonieten, en dat bracht drie jaar honger over Israël."],
    ["Jesaja 28:21", "Jesaja herinnert aan wat de HEERE deed ‘in het dal van Gibeon’."],
    ["Hebreeën 4:8–9", "Jozua bracht het volk nog niet in de echte rust: ‘Er blijft dan een rust over voor het volk Gods.’"]],
  tl: [-1406, -1375], tijd: "ca. 1406–1375 v.Chr.",
  tijdNoot: "Reconstructie: de list van Gibeon en de slag (Jozua 9–10) vallen kort na de intocht, ca. 1406 v.Chr. (uittocht ca. 1446 v.Chr. volgens 1 Koningen 6:1). Hoe oud Jozua bij de intocht was, zegt de Bijbel niet; daarom is het jaar van zijn afscheid en dood (Jozua 24) een ruwe schatting. Wie de uittocht in de 13e eeuw v.Chr. dateert, komt bijna twee eeuwen later uit." },

{ nr: 42, t: "Debora en Barak", ref: "Richteren 4–5", sectie: "richters",
  stappen: ["richteren:debora:1", "richteren:debora:2", "richteren:debora:3", "richteren:debora:4"],
  vorm: "route",
  uitleg: "Israël doet weer wat kwaad is in de ogen van de HEERE. Daarom geeft God hen in de hand van Jabin, de koning van de Kanaänieten in Hazor. Twintig jaar lang onderdrukt hij hen met geweld; zijn legeroverste Sisera heeft negenhonderd ijzeren wagens. Debora, een profetes, richt Israël onder een palmboom tussen Rama en Bethel. Ze roept Barak: de HEERE zegt dat hij met tienduizend man naar de berg Tabor moet gaan. Barak wil alleen gaan als Debora meegaat. Debora zegt dat de eer dan naar een vrouw zal gaan. Bij de beek Kison verslaat de HEERE Sisera en zijn hele leger. Sisera vlucht te voet naar de tent van Jaël. Terwijl hij slaapt, doodt zij hem met een tentpin. Debora en Barak zingen een lied, en het land heeft veertig jaar rust.",
  betekenis: "God redde Zijn volk toen het tot Hem riep (Richteren 4:3), en Hij gaf de eer niet aan een sterke legeraanvoerder. Het lied eindigt: ‘Alzo moeten omkomen al Uw vijanden, o HEERE!’ (Richteren 5:31).",
  wie: ["Debora", "Barak", "Sisera", "Jaël", "Jabin"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Heeft de HEERE, de God Israëls, niet geboden: Ga heen en trek op den berg Thabor?", "Debora", ["Barak", "Jaël"]],
    ["Indien gij met mij trekken zult, zo zal ik heen trekken", "Barak", ["Sisera", "Debora"]],
    ["Wijk in, mijn heer, wijk in tot mij, vrees niet!", "Jaël", ["Debora", "De moeder van Sisera"]],
    ["Waarom vertoeft zijn wagen te komen?", "De moeder van Sisera", ["Jaël", "Debora"]]] },
  quiz: [{ q: "Hoeveel ijzeren wagens had Sisera?", a: ["900", "300", "10.000"], why: "Richteren 4:3" },
    { q: "Waar woonde Debora als ze het volk recht sprak?", a: ["Onder een palmboom tussen Rama en Bethel", "In de stadspoort van Hazor", "Op de berg Tabor"], why: "Richteren 4:5" },
    { q: "Naar welke berg moest Barak gaan?", a: ["De berg Tabor", "De berg Karmel", "De berg Gilboa"], why: "Richteren 4:6" },
    { q: "Wat gaf Jaël aan Sisera toen hij om water vroeg?", a: ["Melk", "Wijn", "Water"], why: "Richteren 4:19" }],
  cross: [["Hebreeën 11:32–34", "Barak wordt genoemd bij hen die door het geloof koninkrijken overwonnen."],
    ["Psalm 83:10", "‘Doe hun als Midian, als Sisera, als Jabin aan de beek Kison.’"],
    ["Richteren 2:16", "Telkens verwekte de HEERE richters, die het volk verlosten."]],
  tl: [-1240, -1120], tijd: "ca. 1240–1120 v.Chr. (onzeker)",
  tijdNoot: "Reconstructie met grote onzekerheid (zie het deel Debora en Gideon): de jaren van onderdrukking en rust in Richteren zijn opgeteld langer dan er tussen Jozua en Saul past als je 1 Koningen 6:1 volgt; veel uitleggers nemen aan dat perioden elkaar overlappen. Debora en Gideon vallen dan ongeveer in de 13e en vroege 12e eeuw v.Chr.; wie de uittocht in de 13e eeuw dateert, komt ruim een eeuw later uit." },

{ nr: 43, t: "Gideon en de driehonderd", ref: "Richteren 6–8", sectie: "richters",
  stappen: ["richteren:debora:5", "richteren:debora:6", "richteren:debora:7", "richteren:debora:8"],
  vorm: "route",
  uitleg: "Zeven jaar lang geeft de HEERE Israël in de hand van de Midianieten, die alles opeten. Gideon dorst tarwe bij de wijnpers, om het te verbergen voor de Midianieten. Daar komt de Engel van de HEERE bij hem: ‘De HEERE is met u, gij strijdbare held!’ In opdracht van God breekt Gideon ’s nachts het altaar van Baäl af. Hij vraagt God twee keer om een teken met een wollen vlies, en God geeft het. Van de tweeëndertigduizend mannen houdt God er maar driehonderd over, ‘opdat zich Israël niet tegen Mij beroeme’. ’s Nachts omsingelen de driehonderd het kamp met bazuinen en lege kruiken met fakkels erin. Ze blazen, breken de kruiken en roepen: ‘Het zwaard van den HEERE, en van Gideon!’ In het kamp keert de HEERE het zwaard van de vijanden tegen elkaar, en ze vluchten.",
  betekenis: "God maakte het leger met opzet klein, zodat iedereen zou zien dat Hij de overwinning gaf (Richteren 7:2). Daarom wilde Gideon later ook geen koning worden: ‘de HEERE zal over u heersen’ (Richteren 8:23).",
  wie: ["Gideon", "Pura", "Midianieten"],
  ontdek: { soort: "volgorde", titel: "Zet het verhaal van Gideon in de goede volgorde.", items: ["De Engel bij de wijnpers", "Het altaar van Baäl afgebroken", "Het teken met het vlies", "Driehonderd mannen blijven over", "Bazuinen, kruiken en fakkels"] },
  quiz: [{ q: "Wat deed Gideon toen de Engel van de HEERE bij hem kwam?", a: ["Tarwe dorsen bij de wijnpers", "Schapen hoeden", "Een altaar bouwen"], why: "Richteren 6:11" },
    { q: "Hoeveel mannen gingen naar huis omdat ze bang waren?", a: ["22.000", "300", "10.000"], why: "Richteren 7:3" },
    { q: "Wat droomde een soldaat in het kamp van Midian?", a: ["Een gerstebrood rolde het kamp in en gooide een tent om", "Zeven magere koeien aten zeven vette koeien op", "Een ladder stond op de aarde en reikte tot de hemel"], why: "Richteren 7:13" },
    { q: "Wat hadden de driehonderd mannen in hun handen?", a: ["Bazuinen en lege kruiken met fakkels", "Zwaarden en schilden", "Bogen en pijlen"], why: "Richteren 7:16" },
    { q: "Wat riepen ze bij het kamp van Midian?", a: ["Het zwaard van den HEERE, en van Gideon!", "Leve koning Gideon, leve Israël!", "Vlucht, de Midianieten komen!"], why: "Richteren 7:20" }],
  cross: [["Jesaja 9:3", "Jesaja vergelijkt Gods verlossing met wat God deed ‘ten dage der Midianieten’."],
    ["Hebreeën 11:32", "Gideon wordt genoemd bij de gelovigen."],
    ["1 Korinthe 1:27", "‘Het zwakke der wereld heeft God uitverkoren, opdat Hij het sterke zou beschamen.’"]],
  tl: [-1240, -1120], tijd: "ca. 1240–1120 v.Chr. (onzeker)",
  tijdNoot: "Reconstructie met grote onzekerheid: zeven jaar onder Midian en veertig jaar rust (Richteren 6:1; 8:28). De perioden van de richters overlappen waarschijnlijk (zie het deel Debora en Gideon); Gideon valt dan ongeveer in de 12e eeuw v.Chr. Andere dateringen komen ruim een eeuw later uit." },

{ nr: 44, t: "Simson wordt geboren; de leeuw bij Timna", ref: "Richteren 13–14", sectie: "richters",
  stappen: ["richteren:simson:0", "richteren:simson:1", "richteren:simson:2"],
  vorm: "plek",
  uitleg: "Veertig jaar lang geeft de HEERE Israël in de hand van de Filistijnen. In Zora verschijnt de Engel van de HEERE aan de vrouw van Manoach, die geen kinderen kan krijgen: ‘gij zult zwanger worden, en een zoon baren.’ Er mag nooit een scheermes op zijn hoofd komen, want hij zal een nazireeër van God zijn. Als Manoach een offer brengt, vaart de Engel op in de vlam van het altaar. De jongen heet Simson, en de HEERE zegent hem. Als hij groot is, wil Simson trouwen met een Filistijns meisje uit Timna. Zijn ouders vragen of er geen vrouw bij hun eigen volk is, maar hij houdt vol. Onderweg scheurt hij een jonge leeuw uiteen, want de Geest van de HEERE komt over hem. Op de bruiloft geeft hij een raadsel op over de honing uit de leeuw, maar zijn vrouw verraadt het antwoord.",
  betekenis: "Zijn ouders begrepen het niet, maar de Bijbel zegt dat het ‘van den HEERE was, dat hij gelegenheid zocht van de Filistijnen’ (Richteren 14:4). God gebruikte Simson om ‘Israël te verlossen uit der Filistijnen hand’ (Richteren 13:5).",
  wie: ["Simson", "Manoach", "Filistijnen"],
  ontdek: { soort: "onthul", titel: "Wat beloofde een nazireeër? Tik op een regel.", items: [
    ["Geen wijn", "Niets drinken of eten wat van de wijnstok komt (Numeri 6:3–4)."],
    ["Geen scheermes", "Het haar mocht niet geknipt worden (Numeri 6:5)."],
    ["Geen dode", "Niet bij het lichaam van een dode komen (Numeri 6:6)."],
    ["Van moeders buik af", "Simson moest zijn hele leven nazireeër zijn (Richteren 13:5)."]] },
  quiz: [{ q: "Uit welke stam kwam Manoach?", a: ["Dan", "Juda", "Benjamin"], why: "Richteren 13:2" },
    { q: "Hoe verdween de Engel van de HEERE bij Manoach en zijn vrouw?", a: ["Hij voer op in de vlam van het altaar", "Hij liep weg over de akker", "Hij verdween in een wolk"], why: "Richteren 13:20" },
    { q: "Wat vond Simson later in het lichaam van de leeuw?", a: ["Een bijenzwerm met honing", "Een gouden ring", "Een slang"], why: "Richteren 14:8" },
    { q: "Hoeveel dagen duurde de bruiloft?", a: ["Zeven", "Drie", "Veertig"], why: "Richteren 14:12" }],
  cross: [["Numeri 6:1–8", "De regels voor een nazireeër."],
    ["Lukas 1:13–15", "Ook bij Johannes de Doper kondigt een engel de geboorte aan; ‘noch wijn, noch sterken drank zal hij drinken’."],
    ["Hebreeën 11:32", "Simson wordt genoemd bij de gelovigen."]],
  tl: [-1100, -1050], tijd: "ca. 1100–1050 v.Chr. (onzeker)",
  tijdNoot: "Reconstructie, onzeker: de Filistijnen heersten veertig jaar (Richteren 13:1), en veel uitleggers laten die tijd deels samenvallen met die van Eli en Samuël, kort vóór koning Saul (ca. 1050 v.Chr.). Andere dateringen schuiven dit op." },

{ nr: 45, t: "Vossen, fakkels en een ezelskaak", ref: "Richteren 15", sectie: "richters",
  stappen: ["richteren:simson:2", "richteren:simson:3"],
  vorm: "plek",
  uitleg: "Als Simson zijn vrouw in Timna wil bezoeken, blijkt dat haar vader haar aan een ander heeft gegeven. Simson vangt driehonderd vossen, zet telkens een fakkel tussen twee staarten en jaagt ze door het koren van de Filistijnen. De Filistijnen verbranden daarop zijn vrouw en haar vader. Dan komen drieduizend mannen van Juda naar de rots Etam: ‘Wist gij niet, dat de Filistijnen over ons heersen?’ Ze binden Simson met twee nieuwe touwen om hem uit te leveren. Bij Lechi komt de Geest van de HEERE over hem, en de touwen worden als verbrande draden. Met een verse ezelskaak verslaat hij duizend man. Daarna heeft hij grote dorst en roept hij tot de HEERE. God laat water komen uit een holte in Lechi.",
  betekenis: "Simson was sterk, maar in zijn dorst merkte hij dat hij helemaal van God afhing: ‘zou ik dan nu van dorst sterven?’ (Richteren 15:18). God gaf water, en Simson noemde de plek ‘De fontein des aanroepers’ (Richteren 15:19).",
  wie: ["Simson", "Filistijnen"],
  ontdek: { soort: "koppel", titel: "Welk getal hoort waarbij?", paren: [
    ["300", "vossen met fakkels (15:4)"],
    ["3000", "mannen van Juda bij de rots Etam (15:11)"],
    ["2", "nieuwe touwen om Simson te binden (15:13)"],
    ["1000", "mannen verslagen met de ezelskaak (15:15)"],
    ["20", "jaren dat Simson Israël richtte (15:20)"]] },
  quiz: [{ q: "Wat zette Simson tussen de staarten van de vossen?", a: ["Een fakkel", "Een bel", "Een steen"], why: "Richteren 15:4" },
    { q: "Wie bonden Simson om hem aan de Filistijnen over te geven?", a: ["Mannen van Juda", "Mannen van Dan", "Zijn broers"], why: "Richteren 15:11–13" },
    { q: "Waarmee versloeg Simson duizend man?", a: ["Met een ezelskaak", "Met een zwaard", "Met een speer"], why: "Richteren 15:15" },
    { q: "Hoe lang richtte Simson Israël?", a: ["Twintig jaar", "Veertig jaar", "Zeven jaar"], why: "Richteren 15:20" }],
  cross: [["Psalm 50:15", "‘Roept Mij aan in den dag der benauwdheid; Ik zal er u uithelpen.’"],
    ["Hebreeën 11:32–34", "Van de gelovigen, onder wie Simson, staat: ‘uit zwakheid krachten hebben gekregen’."]],
  tl: [-1100, -1050], tijd: "ca. 1100–1050 v.Chr. (onzeker)",
  tijdNoot: "Reconstructie, onzeker: Simson richtte Israël twintig jaar ‘in de dagen der Filistijnen’ (Richteren 15:20), volgens veel uitleggers kort vóór koning Saul (ca. 1050 v.Chr.). Andere dateringen schuiven dit op." },

{ nr: 46, t: "Simson en Delila", ref: "Richteren 16", sectie: "richters",
  stappen: ["richteren:simson:4", "richteren:simson:5", "richteren:simson:6"],
  vorm: "plek",
  uitleg: "In Gaza wachten de Filistijnen Simson op. Maar om middernacht tilt hij de deuren van de stadspoort met de posten eruit en draagt ze weg. Daarna krijgt hij Delila lief, een vrouw aan de beek Sorek. De vorsten van de Filistijnen beloven haar ieder elfhonderd zilverstukken als ze ontdekt waar zijn kracht in zit. Drie keer misleidt Simson haar, maar ze blijft aandringen, tot hij haar alles vertelt. Terwijl hij slaapt, laat ze de zeven haarlokken van zijn hoofd afscheren. Nu is de HEERE van hem geweken. De Filistijnen steken zijn ogen uit, en in Gaza moet hij malen in de gevangenis. Op een feest voor hun god Dagon bidt Simson nog één keer om kracht. Hij duwt tegen de twee middelste pilaren, en het huis stort in. Zo sterven er bij zijn dood meer Filistijnen dan in zijn hele leven.",
  betekenis: "Simsons kracht zat niet in zijn haar zelf, maar in de HEERE: toen hij zijn nazireeërschap prijsgaf, ‘wist hij niet, dat de HEERE van hem geweken was’ (Richteren 16:20). Toch hoorde God zijn laatste gebed (Richteren 16:28–30).",
  wie: ["Simson", "Delila", "Filistijnen"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Overreed hem, en zie, waarin zijn grote kracht zij", "De vorsten van de Filistijnen", ["Simson", "De mannen van Gaza"]],
    ["De Filistijnen over u, Simson!", "Delila", ["De vorsten van de Filistijnen", "Manoach"]],
    ["Onze god heeft onze vijand Simson in onze hand gegeven", "De Filistijnen", ["Delila", "Simson"]],
    ["Heere, HEERE! gedenk toch mijner, en sterk mij toch alleenlijk ditmaal", "Simson", ["Delila", "Manoach"]]] },
  quiz: [{ q: "Wat droeg Simson weg uit Gaza?", a: ["De deuren van de stadspoort, met de posten", "Het beeld van Dagon uit de tempel", "Een kist met het zilver van de vorsten"], why: "Richteren 16:3" },
    { q: "Hoeveel zilverstukken beloofde elke vorst aan Delila?", a: ["1100", "30", "50"], why: "Richteren 16:5" },
    { q: "Hoeveel haarlokken werden van Simsons hoofd geschoren?", a: ["Zeven", "Drie", "Twaalf"], why: "Richteren 16:19" },
    { q: "Wat moest Simson doen in de gevangenis in Gaza?", a: ["Malen", "Stenen bakken", "Hout hakken"], why: "Richteren 16:21" }],
  cross: [["Richteren 13:5", "Al vóór zijn geboorte was gezegd: ‘hij zal beginnen Israël te verlossen uit der Filistijnen hand.’"],
    ["1 Samuël 5:1–4", "Later valt het beeld van Dagon in Asdod voorover voor de ark van de HEERE."]],
  tl: [-1100, -1050], tijd: "ca. 1100–1050 v.Chr. (onzeker)",
  tijdNoot: "Reconstructie, onzeker: aan het eind van de twintig jaar dat Simson richtte (Richteren 15:20; 16:31), volgens veel uitleggers kort vóór koning Saul (ca. 1050 v.Chr.)." },

{ nr: 47, t: "Naomi en Ruth", ref: "Ruth 1–4", sectie: "richters",
  stappen: ["ruth:ruth:0", "ruth:ruth:1", "ruth:ruth:2", "ruth:ruth:3", "ruth:ruth:4", "ruth:ruth:5", "ruth:ruth:6"],
  vorm: "stamboom",
  uitleg: "In de tijd van de richters is er honger in Bethlehem. Elimelech en Naomi trekken met hun twee zonen naar Moab. Daar sterven Elimelech en, ongeveer tien jaar later, ook de zonen. Naomi gaat terug, en haar schoondochter Ruth uit Moab gaat mee: ‘uw volk is mijn volk, en uw God mijn God.’ In Bethlehem raapt Ruth aren op de akker van Boaz, een familielid van Elimelech. Boaz is goed voor haar. Hij is een losser: een familielid dat het land en de naam van de familie mag redden. Boaz wil die taak op zich nemen. Bij de stadspoort regelt hij het, met tien oudsten als getuigen, en hij trouwt met Ruth. De HEERE geeft hun een zoon, Obed, en Obed wordt de grootvader van koning David.",
  betekenis: "Achter alles is de HEERE aan het werk: Hij geeft Zijn volk weer brood (Ruth 1:6), en de vrouwen zeggen: ‘Geloofd zij de HEERE’ (Ruth 4:14). Een vreemdelinge die ‘onder Zijn vleugelen’ kwam schuilen (Ruth 2:12), komt in het geslachtsregister van de Heere Jezus (Mattheüs 1:5).",
  wie: ["Naomi", "Ruth", "Boaz", "Obed"],
  kw: "god",
  ontdek: { soort: "stamboom", titel: "Van Perez tot David (Ruth 4:18–22)", rijen: [["Perez"], ["Hezron"], ["Ram"], ["Amminadab"], ["Nahesson"], ["Salmon"], ["Boaz", "Ruth"], ["Obed"], ["Isaï"], ["David"]] },
  quiz: [{ q: "Wie zei: ‘uw volk is mijn volk, en uw God mijn God’?", a: ["Ruth", "Naomi", "Orpa"], why: "Ruth 1:16" },
    { q: "Wanneer kwamen Naomi en Ruth in Bethlehem aan?", a: ["In het begin van de gersteoogst", "In de druivenoogst", "Midden in de winter"], why: "Ruth 1:22" },
    { q: "Hoeveel oudsten haalde Boaz erbij in de poort?", a: ["Tien", "Twaalf", "Zeventig"], why: "Ruth 4:2" },
    { q: "Wie was de zoon van Obed?", a: ["Isaï", "David", "Salomo"], why: "Ruth 4:22" }],
  cross: [["Mattheüs 1:5–6", "‘Booz gewon Obed bij Ruth, en Obed gewon Jessai’: Ruth staat in het geslachtsregister van de Heere Jezus."],
    ["Leviticus 19:9–10", "Gods regel voor de oogst: laat de gevallen aren liggen voor de arme en de vreemdeling."],
    ["Psalm 146:9", "‘De HEERE bewaart de vreemdelingen; Hij houdt den wees en de weduwe staande.’"]],
  tl: [-1150, -1100], tijd: "ca. 1150–1100 v.Chr. (onzeker)",
  tijdNoot: "Reconstructie, onzeker. Ruth 1:1 zegt alleen: ‘in de dagen, als de richters richtten’. Terugrekenen vanaf David (koning ca. 1010 v.Chr.) met gewone generaties geeft ruwweg 1150–1100 v.Chr.; omdat het geslachtsregister mogelijk niet alle generaties noemt, kan het ook eerder zijn." },

{ nr: 48, t: "Hanna bidt; God roept Samuël", ref: "1 Samuël 1–3", sectie: "koningen",
  stappen: ["1samuel:samuel:0", "1samuel:samuel:1"],
  vorm: "plek",
  uitleg: "Elkana gaat elk jaar met zijn gezin naar Silo om de HEERE te aanbidden en te offeren. Zijn vrouw Hanna heeft geen kinderen. Peninna, zijn andere vrouw, tergt (plaagt) haar daarom. In Silo bidt Hanna huilend en belooft: als U mij een zoon geeft, zal ik hem aan de HEERE geven, al de dagen van zijn leven. Eli ziet alleen haar lippen bewegen en denkt dat ze dronken is. De HEERE denkt aan Hanna, en ze noemt haar zoon Samuël. Als hij gespeend is, brengt ze hem naar Eli in Silo, en ze zingt een lofzang. Op een nacht roept de HEERE Samuël. Drie keer loopt de jongen naar Eli. De vierde keer zegt hij: ‘Spreek, want Uw knecht hoort.’",
  betekenis: "God vergat Hanna niet: ‘de HEERE gedacht aan haar’ (1 Samuël 1:19). En in een tijd waarin ‘het woord des HEEREN … dierbaar’ was (1 Samuël 3:1), begon Hij weer tot Zijn volk te spreken door Samuël.",
  wie: ["Hanna", "Elkana", "Eli", "Samuël"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Ben ik u niet beter dan tien zonen?", "Elkana", ["Eli", "Samuël"]],
    ["Hoe lang zult gij u dronken aanstellen?", "Eli", ["Elkana", "Peninna"]],
    ["Mijn hart springt van vreugde op in den HEERE", "Hanna", ["Peninna", "Eli"]],
    ["Spreek, want Uw knecht hoort", "Samuël", ["Eli", "Elkana"]]] },
  quiz: [{ q: "Wat beloofde Hanna als God haar een zoon zou geven?", a: ["Ze zou hem aan de HEERE geven, al de dagen van zijn leven", "Ze zou hem koning maken", "Ze zou een nieuw altaar bouwen"], why: "1 Samuël 1:11" },
    { q: "Wat dacht Eli toen hij Hanna zag bidden?", a: ["Dat ze dronken was", "Dat ze ziek was", "Dat ze sliep"], why: "1 Samuël 1:13" },
    { q: "Wat maakte Hanna elk jaar voor Samuël?", a: ["Een kleine rok (een jasje)", "Een harp", "Een paar schoenen"], why: "1 Samuël 2:19" },
    { q: "Bij de hoeveelste keer begreep Eli dat de HEERE Samuël riep?", a: ["De derde keer", "De eerste keer", "De zevende keer"], why: "1 Samuël 3:8" }],
  cross: [["Lukas 1:46–47", "Maria zingt een lofzang die lijkt op die van Hanna: ‘Mijn ziel maakt groot den Heere.’"],
    ["Psalm 99:6", "Samuël wordt genoemd ‘onder de aanroepers Zijns Naams’, samen met Mozes en Aäron."]],
  tl: [-1100, -1090], tijd: "ca. 1100 v.Chr. (ruwe schatting)",
  tijdNoot: "Ruwe schatting. Wanneer Samuël geboren werd, staat niet in de Bijbel. Terugrekenend vanaf Saul (koning ca. 1050 v.Chr.; vergelijk Handelingen 13:21) en David (ca. 1010 v.Chr.) komt men rond 1100 v.Chr. uit. Andere dateringen schuiven dit op." },

{ nr: 49, t: "De ark weggevoerd en teruggebracht", ref: "1 Samuël 4–7", sectie: "koningen",
  stappen: ["1samuel:samuel:2", "1samuel:samuel:3", "1samuel:samuel:4"],
  vorm: "route",
  uitleg: "Israël verliest een slag tegen de Filistijnen. Dan halen de oudsten de ark van het verbond uit Silo, ‘opdat zij ons verlosse’. Maar Israël verliest opnieuw: dertigduizend man sneuvelen, Hofni en Pinehas sterven en de ark wordt buitgemaakt. Als de oude Eli dat hoort, valt hij achterover van zijn stoel en sterft. In Asdod zetten de Filistijnen de ark naast hun god Dagon. Twee ochtenden achter elkaar ligt Dagon voorover op de grond. Overal waar de ark komt, slaat de HEERE de mensen met gezwellen. Na zeven maanden sturen de Filistijnen de ark terug naar Beth-Semes, op een nieuwe wagen met twee koeien. Daarna komt de ark in Kirjath-Jearim. Twintig jaar later roept Samuël het volk tot bekering. De HEERE jaagt de Filistijnen weg met donder, en Samuël zet een steen neer: Eben-Haëzer.",
  betekenis: "De ark was geen geluksbrenger. Het volk nam de ark mee ‘opdat zij ons verlosse’ (1 Samuël 4:3), maar het had nog vreemde goden (1 Samuël 7:3). Toen het volk die wegdeed en de HEERE alleen diende, hielp Hij hen: ‘Tot hiertoe heeft de HEERE ons geholpen’ (1 Samuël 7:4, 12).",
  wie: ["Eli", "Samuël", "Filistijnen"],
  ontdek: { soort: "volgorde", titel: "Volg de reis van de ark. Waar ging hij heen?", items: ["Eben-Haëzer (het slagveld)", "Asdod", "Gath", "Ekron", "Beth-Semes", "Kirjath-Jearim"] },
  quiz: [{ q: "Waarom haalden de oudsten de ark naar het slagveld?", a: ["Ze dachten dat de ark hen zou verlossen", "God had het bevolen", "Samuël vroeg erom"], why: "1 Samuël 4:3" },
    { q: "Wat gebeurde er met het beeld van Dagon?", a: ["Het lag voorover op de grond voor de ark", "Het begon te spreken", "Het werd van goud"], why: "1 Samuël 5:3" },
    { q: "Hoe lang was de ark in het land van de Filistijnen?", a: ["Zeven maanden", "Zeven dagen", "Twintig jaar"], why: "1 Samuël 6:1" },
    { q: "Wat zei Samuël toen hij de steen Eben-Haëzer neerzette?", a: ["Tot hiertoe heeft de HEERE ons geholpen", "De eer is weggevoerd uit Israël", "Hier is de ark gevonden"], why: "1 Samuël 7:12" }],
  cross: [["Psalm 78:60–61", "God verliet de tabernakel in Silo ‘en Hij gaf Zijn sterkte in de gevangenis’."],
    ["Jeremia 7:12", "God zegt eeuwen later: ga naar Silo en zie wat Ik daar gedaan heb vanwege de boosheid van Mijn volk."]],
  tl: [-1100, -1050], tijd: "ca. 1100–1050 v.Chr. (onzeker)",
  tijdNoot: "Reconstructie, onzeker: vóór koning Saul (ca. 1050 v.Chr.). Eli richtte Israël veertig jaar (1 Samuël 4:18), en de ark bleef twintig jaar in Kirjath-Jearim (1 Samuël 7:2). De precieze jaren zijn niet uit de Bijbel te berekenen." },

{ nr: 50, t: "Israël wil een koning; Saul wordt gezalfd", ref: "1 Samuël 8–10", sectie: "koningen",
  stappen: ["1samuel:samuel:5", "1samuel:samuel:6", "1samuel:samuel:7"],
  vorm: "route",
  uitleg: "Samuël is oud, en zijn zonen zijn oneerlijke rechters. De oudsten van Israël komen naar Rama: ‘zet nu een koning over ons, om ons te richten, gelijk al de volken hebben.’ Samuël vindt dat kwaad, maar de HEERE zegt: ‘zij hebben u niet verworpen, maar zij hebben Mij verworpen.’ Samuël waarschuwt wat een koning van hen zal nemen, maar het volk wil niet luisteren. Saul is een jonge man uit Benjamin, die boven iedereen uitsteekt. Hij zoekt de ezelinnen van zijn vader en komt bij Samuël. Samuël giet olie op zijn hoofd: de HEERE heeft hem gezalfd tot voorganger over Zijn erfdeel. Later wordt Saul in Mizpa door het lot aangewezen. Hij heeft zich verstopt tussen de bagage. Het volk juicht: ‘de koning leve!’",
  betekenis: "Het volk wilde een koning ‘gelijk al de volken’ (1 Samuël 8:5, 20), terwijl de HEERE Zelf hun Koning was (1 Samuël 12:12). Toch gaf God hun een koning, zoals Mozes al had voorzegd (Deuteronomium 17:14–15).",
  wie: ["Samuël", "Saul", "Kis"],
  ontdek: { soort: "onthul", titel: "Wat zou een koning van het volk nemen? (1 Samuël 8:11–17)", items: [
    ["Zonen", "Voor zijn wagens en ruiters, en om zijn akker te ploegen en zijn wapens te maken (8:11–12)."],
    ["Dochters", "Om zalf te maken, te koken en te bakken (8:13)."],
    ["Akkers", "Zijn beste akkers, wijngaarden en olijfgaarden, voor zijn knechten (8:14)."],
    ["Een tiende", "Een tiende van het zaad, de wijngaarden en de kudden (8:15, 17)."]] },
  quiz: [{ q: "Waarom wilden de oudsten een koning?", a: ["Om te zijn zoals alle andere volken", "Omdat Samuël dat voorstelde", "Omdat God het had bevolen"], why: "1 Samuël 8:5" },
    { q: "Wat zocht Saul toen hij bij Samuël kwam?", a: ["De ezelinnen van zijn vader", "Een zwaard", "Een plek om te wonen"], why: "1 Samuël 9:3" },
    { q: "Uit welke stam kwam Saul?", a: ["Benjamin", "Juda", "Levi"], why: "1 Samuël 9:21" },
    { q: "Waar had Saul zich verstopt toen hij koning werd?", a: ["Tussen de bagage", "In een grot", "Op het dak"], why: "1 Samuël 10:22" }],
  cross: [["Deuteronomium 17:14–15", "Mozes had voorzegd dat Israël een koning zou willen, en dat God die koning zou kiezen."],
    ["Handelingen 13:21", "Paulus: ‘En van toen aan begeerden zij een koning; en God gaf hun Saul, den zoon van Kis.’"]],
  tl: [-1050, -1050], tijd: "ca. 1050 v.Chr.",
  tijdNoot: "Reconstructie: Saul regeerde veertig jaar (Handelingen 13:21) en stierf vlak voordat David koning werd, ca. 1010 v.Chr. in de gangbare chronologie. Andere dateringen schuiven deze jaren enkele tientallen jaren op." },

{ nr: 51, t: "Saul verworpen, David gezalfd", ref: "1 Samuël 13–16; Psalm 23", sectie: "koningen",
  stappen: ["1samuel:saul-david:0", "1samuel:saul-david:1", "1samuel:saul-david:2", "1samuel:saul-david:3"],
  vorm: "plek",
  uitleg: "Saul wacht in Gilgal zeven dagen op Samuël. Als die niet op tijd komt, brengt hij zelf het brandoffer. Samuël zegt: ‘Gij hebt zottelijk (dwaas) gedaan’; de HEERE heeft Zich een man gezocht naar Zijn hart. Later moet Saul Amalek helemaal vernietigen (‘verbannen’), maar hij spaart koning Agag en de beste dieren. Samuël zegt: ‘gehoorzamen is beter dan slachtoffer.’ Dan stuurt God Samuël naar Isaï in Bethlehem. Zeven zonen gaan voorbij, maar de HEERE zegt: ‘de mens ziet aan, wat voor ogen is, maar de HEERE ziet het hart aan.’ De jongste, David, wordt van de schapen gehaald en gezalfd. De Geest van de HEERE komt over hem. Als Saul verschrikt wordt door een boze geest van de HEERE, speelt David voor hem op de harp.",
  betekenis: "God koos niet op uiterlijk, maar op het hart (1 Samuël 16:7). David, die als herder op de schapen paste, schreef later: ‘De HEERE is mijn Herder, mij zal niets ontbreken’ (Psalm 23:1).",
  wie: ["Saul", "Samuël", "Isaï", "David", "Agag"],
  ontdek: { soort: "onthul", titel: "David, de herder: tik op een kaart.", items: [
    ["Bij de schapen", "Toen Samuël kwam, was David de jongste en weidde hij de schapen (1 Samuël 16:11)."],
    ["Leeuw en beer", "Als herder redde hij een schaap uit de mond van een leeuw en van een beer (1 Samuël 17:34–35)."],
    ["Psalm 23", "David schrijft: ‘De HEERE is mijn Herder, mij zal niets ontbreken’, ook ‘in een dal der schaduw des doods’ (Psalm 23:1, 4)."],
    ["Herder van Israël", "De HEERE had tegen David gezegd: ‘Gij zult Mijn volk Israël weiden’ (2 Samuël 5:2)."],
    ["De goede Herder", "De Heere Jezus zegt: ‘Ik ben de goede Herder; de goede herder stelt zijn leven voor de schapen’ (Johannes 10:11)."]] },
  quiz: [{ q: "Wat deed Saul in Gilgal, terwijl hij op Samuël had moeten wachten?", a: ["Hij bracht zelf het brandoffer", "Hij ging naar huis", "Hij viel de Filistijnen aan"], why: "1 Samuël 13:9" },
    { q: "Wat zei Samuël tegen Saul na de strijd tegen Amalek?", a: ["Gehoorzamen is beter dan slachtoffer", "Je hebt het goed gedaan", "Breng nog meer offers"], why: "1 Samuël 15:22" },
    { q: "Waar kijkt de HEERE naar, volgens 1 Samuël 16?", a: ["Het hart", "De lengte", "De kleren"], why: "1 Samuël 16:7" },
    { q: "Hoe begint Psalm 23?", a: ["De HEERE is mijn Herder, mij zal niets ontbreken", "Wees mij genadig, o God! naar Uw goedertierenheid", "Hoe lang, HEERE, zult Gij mij steeds vergeten?"], why: "Psalm 23:1" }],
  cross: [["Psalm 23:1–4", "David bezingt de HEERE als zijn Herder: ‘Uw stok en Uw staf, die vertroosten mij.’"],
    ["Handelingen 13:22", "God over David: ‘Ik heb gevonden David, den zoon van Jesse; een man naar Mijn hart.’"],
    ["Johannes 10:11", "De Heere Jezus is de goede Herder, Die Zijn leven geeft voor de schapen."]],
  tl: [-1050, -1025], tijd: "ca. 1050–1025 v.Chr. (onzeker)",
  tijdNoot: "Reconstructie: Saul werd koning ca. 1050 v.Chr. (Handelingen 13:21: veertig jaar). David was dertig toen hij koning werd (2 Samuël 5:4), in de gangbare chronologie ca. 1010 v.Chr., en werd dus rond 1040 geboren. Hoe oud hij bij de zalving was, zegt de Bijbel niet." },

{ nr: 52, t: "David en Goliath", ref: "1 Samuël 17", sectie: "koningen",
  stappen: ["1samuel:saul-david:4"],
  vorm: "plek",
  uitleg: "In het Eikdal staan de Filistijnen en Israël tegenover elkaar, op twee bergen. Veertig dagen lang daagt de reus Goliath uit Gath Israël uit: ‘Geeft mij een man, dat wij te zamen strijden!’ Saul en heel Israël zijn erg bang. David brengt eten voor zijn broers en hoort hoe de Filistijn de slagorden van de levende God hoont. Hij zegt tegen Saul: de HEERE Die mij van de leeuw en de beer gered heeft, zal mij ook redden uit de hand van deze Filistijn. Het harnas van Saul doet hij weer uit. Hij gaat met zijn staf, zijn slinger en vijf gladde stenen uit de beek. ‘Gij komt tot mij met een zwaard … maar ik kom tot u in den Naam van den HEERE der heirscharen.’ De eerste steen treft Goliath in zijn voorhoofd, en hij valt voorover op de grond.",
  betekenis: "David vocht niet om zelf beroemd te worden, maar ‘de ganse aarde zal weten, dat Israël een God heeft’ (1 Samuël 17:46). ‘De HEERE verlost niet door het zwaard, noch door de spies; want de krijg is des HEEREN’ (1 Samuël 17:47).",
  wie: ["David", "Goliath", "Saul"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Geeft mij een man, dat wij te zamen strijden!", "Goliath", ["Saul", "Eliab"]],
    ["Ik ken uw vermetelheid, en de boosheid uws harten wel", "Eliab, de oudste broer van David", ["Saul", "Goliath"]],
    ["Gij zult niet kunnen heengaan tot dezen Filistijn", "Saul", ["Eliab", "Isaï"]],
    ["De krijg is des HEEREN", "David", ["Saul", "Goliath"]]] },
  quiz: [{ q: "Hoe lang daagde Goliath Israël uit?", a: ["Veertig dagen", "Zeven dagen", "Een jaar"], why: "1 Samuël 17:16" },
    { q: "Waarom deed David het harnas van Saul weer uit?", a: ["Hij had het nooit geprobeerd en kon er niet in lopen", "Het was van de koning, en dat mocht hij niet dragen", "Goliath zou hem eraan herkennen"], why: "1 Samuël 17:39" },
    { q: "Hoeveel gladde stenen koos David uit de beek?", a: ["Vijf", "Eén", "Twaalf"], why: "1 Samuël 17:40" },
    { q: "Waar trof de steen Goliath?", a: ["In zijn voorhoofd", "In zijn hart", "In zijn knie"], why: "1 Samuël 17:49" }],
  cross: [["Psalm 144:1", "David: ‘Gezegend zij de HEERE, mijn Rotssteen, Die mijn handen onderwijst ten strijde.’"],
    ["2 Kronieken 20:15", "Later klinkt hetzelfde tegen koning Josafat: ‘de strijd is niet uwe, maar Gods.’"]],
  tl: [-1025, -1020], tijd: "ca. 1025 v.Chr. (onzeker)",
  tijdNoot: "Reconstructie, onzeker: David was nog een jongeman (1 Samuël 17:33) en werd op zijn dertigste koning (2 Samuël 5:4), in de gangbare chronologie ca. 1010 v.Chr. Hoe oud hij precies was bij het gevecht, staat niet in de Bijbel." },

{ nr: 53, t: "Jonathan en David", ref: "1 Samuël 14; 18", sectie: "koningen",
  stappen: ["1samuel:saul-david:0", "1samuel:saul-david:5"],
  vorm: "plek",
  uitleg: "Jonathan, de zoon van Saul, klimt met alleen zijn wapendrager naar de wachtpost van de Filistijnen. ‘Bij den HEERE is geen verhindering, om te verlossen door velen of door weinigen.’ God geeft een grote overwinning. Als David later Goliath verslagen heeft, wordt de ziel van Jonathan verbonden aan de ziel van David. Jonathan heeft hem lief als zichzelf. Hij sluit een verbond met hem en geeft hem zijn mantel, zijn kleren, zijn zwaard, zijn boog en zijn gordel. Maar Saul wordt jaloers als de vrouwen zingen: ‘Saul heeft zijn duizenden verslagen, maar David zijn tienduizenden!’ Toch blijft Jonathan Davids vriend en spreekt hij goed over hem bij zijn vader.",
  betekenis: "Jonathan wist dat David koning zou worden in zijn plaats, en toch had hij hem lief (1 Samuël 23:17). Zijn moed bij Michmas kwam uit vertrouwen op God, niet uit het aantal soldaten (1 Samuël 14:6).",
  wie: ["Jonathan", "David", "Saul", "Wapendrager"],
  ontdek: { soort: "koppel", titel: "Wat hoort bij elkaar?", paren: [
    ["Bozes en Sene", "twee scherpe rotspunten bij Michmas (14:4)"],
    ["Honingraat", "Jonathan doopte er zijn staf in (14:27)"],
    ["Mantel, zwaard en boog", "Jonathan gaf ze aan David (18:4)"],
    ["Tienduizenden", "wat de vrouwen over David zongen (18:7)"],
    ["Een spies", "Saul gooide die naar David (18:10–11)"]] },
  quiz: [{ q: "Wie ging met Jonathan mee naar de wachtpost van de Filistijnen?", a: ["Zijn wapendrager", "Zijn vader Saul", "David"], why: "1 Samuël 14:6" },
    { q: "Wat gaf Jonathan aan David toen ze een verbond sloten?", a: ["Zijn mantel, kleren, zwaard, boog en gordel", "Een gouden ring en een zilveren beker", "Een paard en een wagen"], why: "1 Samuël 18:4" },
    { q: "Waarom werd Saul jaloers op David?", a: ["De vrouwen zongen dat David tienduizenden verslagen had", "David zei dat hij zelf koning wilde worden", "David speelde beter op de harp dan Saul"], why: "1 Samuël 18:7–8" },
    { q: "Wat gooide Saul naar David terwijl die op de harp speelde?", a: ["Een spies", "Een steen", "Een beker"], why: "1 Samuël 18:10–11" }],
  cross: [["2 Samuël 1:26", "David over Jonathan: ‘Ik ben benauwd om uwentwil, mijn broeder Jonathan!’"],
    ["2 Samuël 9:1", "Om Jonathan doet David later goed aan diens zoon Mefiboseth."],
    ["Spreuken 17:17", "‘Een vriend heeft te aller tijd lief.’"]],
  tl: [-1050, -1020], tijd: "ca. 1050–1020 v.Chr. (onzeker)",
  tijdNoot: "Reconstructie, onzeker: Michmas valt vroeg in de regering van Saul (ca. 1050 v.Chr.), de vriendschap met David na het gevecht met Goliath. David werd ca. 1010 v.Chr. koning (2 Samuël 5:4); de precieze jaren staan niet in de Bijbel." },

{ nr: 54, t: "David op de vlucht voor Saul", ref: "1 Samuël 18–22; 24", sectie: "koningen",
  stappen: ["1samuel:saul-david:5", "1samuel:saul-david:6", "1samuel:saul-david:7"],
  vorm: "route",
  uitleg: "Saul probeert David te doden. Michal laat David ’s nachts door een venster zakken, en Jonathan waarschuwt hem. In Nob krijgt David van de priester Achimelech het heilige brood en het zwaard van Goliath. In Gath doet hij alsof hij gek is. Daarna verbergt hij zich in de spelonk van Adullam, en ongeveer vierhonderd mannen komen bij hem. Saul laat vijfentachtig priesters van Nob doden. In de woestijn van En-Gedi gaat Saul een spelonk in waar David en zijn mannen zitten. David snijdt stilletjes een slip van Sauls mantel af, maar hij doet hem geen kwaad: ‘hij is de gezalfde des HEEREN!’ Saul huilt: ‘Gij zijt rechtvaardiger dan ik.’",
  betekenis: "David nam geen wraak, maar liet het oordeel aan God over: ‘De HEERE zal richten tussen mij en tussen u’ (1 Samuël 24:13). Psalm 57 en 142 zijn gebeden van David ‘in de spelonk’.",
  wie: ["David", "Saul", "Jonathan", "Michal", "Achimelech", "Doëg"],
  ontdek: { soort: "kaart", vraag: "Tik op En-Gedi, waar David Saul spaarde in de spelonk.", id: "engedi", v: "kanaan" },
  quiz: [{ q: "Hoe ontsnapte David uit zijn huis?", a: ["Michal liet hem door een venster zakken", "Hij groef een tunnel", "Jonathan bracht hem weg op een paard"], why: "1 Samuël 19:12" },
    { q: "Welk zwaard kreeg David in Nob?", a: ["Het zwaard van Goliath", "Het zwaard van Saul", "Het zwaard van Jonathan"], why: "1 Samuël 21:9" },
    { q: "Hoeveel mannen kwamen bij David in de spelonk van Adullam?", a: ["Ongeveer vierhonderd", "Twaalf", "Drieduizend"], why: "1 Samuël 22:2" },
    { q: "Wat sneed David af in de spelonk bij En-Gedi?", a: ["Een slip van Sauls mantel", "Een lok van Sauls haar", "Het touw van Sauls tent"], why: "1 Samuël 24:5" }],
  cross: [["Psalm 57:1", "Een psalm van David ‘als hij voor Sauls aangezicht vlood in de spelonk’."],
    ["Mattheüs 12:3–4", "De Heere Jezus herinnert aan David, die de toonbroden at in het huis van God."],
    ["Romeinen 12:19", "‘Wreekt uzelven niet … Mij komt de wraak toe; Ik zal het vergelden, zegt de Heere.’"]],
  tl: [-1020, -1010], tijd: "ca. 1020–1010 v.Chr. (onzeker)",
  tijdNoot: "Reconstructie, onzeker: de laatste jaren van Saul, die vlak voordat David koning werd stierf (ca. 1010 v.Chr. in de gangbare chronologie). Hoe lang David op de vlucht was, zegt de Bijbel niet precies; alleen dat hij een jaar en vier maanden in het land van de Filistijnen woonde (1 Samuël 27:7)." },

{ nr: 55, t: "Sauls laatste nacht en zijn dood op de Gilboa", ref: "1 Samuël 26; 28; 31; 2 Samuël 1", sectie: "koningen",
  stappen: ["1samuel:saul-david:7", "1samuel:saul-david:10", "2samuel:david:0"],
  vorm: "plek",
  uitleg: "In de woestijn van Zif spaart David opnieuw het leven van Saul. Hij neemt alleen de spies en de waterfles mee die bij het hoofd van Saul liggen. Later trekken de Filistijnen op tegen Israël, en Saul is heel bang. Hij vraagt de HEERE om raad, maar de HEERE antwoordt hem niet: niet door dromen, niet door de urim en niet door profeten. Saul had zelf de waarzeggers uit het land weggedaan. Toch gaat hij nu verkleed naar een vrouw met een waarzeggende geest in Endor. Samuël zegt tegen hem: ‘morgen zult gij en uw zonen bij mij zijn.’ De volgende dag verliest Israël op het gebergte Gilboa. Jonathan en twee broers sneuvelen, en Saul valt in zijn eigen zwaard. Als David het hoort, rouwt hij en zingt hij een klaaglied: ‘hoe zijn de helden gevallen!’",
  betekenis: "Saul stierf ‘in zijn overtreding’: hij hield zich niet aan het woord van de HEERE en zocht een waarzegster in plaats van God (1 Kronieken 10:13–14). Wat na de dood komt, zegt Hebreeën 9:27: ‘het is den mensen gezet, eenmaal te sterven, en daarna het oordeel.’",
  wie: ["Saul", "David", "Samuël", "Jonathan", "Abisaï"],
  kw: "eeuwigheid",
  ontdek: { soort: "volgorde", titel: "Zet de laatste dagen van Saul in de goede volgorde.", items: ["David neemt de spies en de waterfles van Saul mee", "De HEERE antwoordt Saul niet meer", "Saul gaat naar de waarzegster in Endor", "De slag op de Gilboa", "David zingt een klaaglied"] },
  quiz: [{ q: "Wat nam David mee bij de slapende Saul?", a: ["De spies en de waterfles", "Zijn kroon", "Zijn mantel"], why: "1 Samuël 26:12" },
    { q: "Hoe antwoordde de HEERE toen Saul Hem om raad vroeg?", a: ["Niet: niet door dromen, niet door de urim, niet door profeten", "Door een engel in de nacht", "Door een teken aan de hemel"], why: "1 Samuël 28:6" },
    { q: "Op welk gebergte verloor Israël van de Filistijnen?", a: ["Gilboa", "Karmel", "Tabor"], why: "1 Samuël 31:1" },
    { q: "Wie haalden de lichamen van Saul en zijn zonen van de muur van Beth-San?", a: ["De mannen van Jabes in Gilead", "De mannen van Juda", "De Amalekieten"], why: "1 Samuël 31:11–12" }],
  cross: [["Hebreeën 9:27", "‘Het is den mensen gezet, eenmaal te sterven, en daarna het oordeel.’"],
    ["1 Kronieken 10:13–14", "Saul stierf omdat hij het woord van de HEERE niet hield en een waarzegster om raad vroeg."],
    ["Deuteronomium 18:10–12", "God verbiedt waarzeggerij en het vragen van de doden: ‘al wie zulks doet, is den HEERE een gruwel’."]],
  tl: [-1010, -1010], tijd: "ca. 1010 v.Chr.",
  tijdNoot: "Reconstructie: Saul stierf vlak voordat David op zijn dertigste koning werd (2 Samuël 5:4), in de gangbare chronologie ca. 1010 v.Chr. Andere dateringen schuiven dit enkele tientallen jaren op." },

{ nr: 56, t: "David koning in Hebron en Jeruzalem", ref: "2 Samuël 2; 5", sectie: "koningen",
  stappen: ["2samuel:david:1", "2samuel:david:2", "2samuel:david:3"],
  vorm: "plek",
  uitleg: "Na de dood van Saul vraagt David de HEERE: ‘Zal ik optrekken in een der steden van Juda?’ God zegt: naar Hebron. Daar zalven de mannen van Juda David tot koning over het huis van Juda. Abner maakt Isboseth, een zoon van Saul, koning over de rest van Israël. Er komt een lange strijd, en David wordt steeds sterker. Dan komen alle oudsten van Israël naar Hebron en zalven David tot koning over heel Israël. David is dertig jaar en zal veertig jaar regeren: zeven jaar en zes maanden in Hebron, drieëndertig jaar in Jeruzalem. Hij neemt de burcht Sion in, en die wordt de stad van David. ‘David nu ging geduriglijk voort, en werd groot; want de HEERE, de God der heirscharen, was met hem.’",
  betekenis: "David greep het koningschap niet zelf, maar wachtte tot God het hem gaf; hij merkte ‘dat de HEERE hem tot een koning over Israël bevestigd had’ (2 Samuël 5:12). God had gezegd: ‘Gij zult Mijn volk Israël weiden’ (2 Samuël 5:2).",
  wie: ["David", "Abner", "Isboseth", "Joab"],
  ontdek: { soort: "onthul", titel: "David werd drie keer gezalfd. Tik op een plaats.", items: [
    ["Bethlehem", "Samuël zalft de jonge David in het midden van zijn broers (1 Samuël 16:13)."],
    ["Hebron", "De mannen van Juda zalven David tot koning over het huis van Juda (2 Samuël 2:4)."],
    ["Weer Hebron", "Alle oudsten van Israël zalven David tot koning over heel Israël (2 Samuël 5:3)."],
    ["Jeruzalem", "David neemt de burcht Sion in: de stad van David (2 Samuël 5:7)."]] },
  quiz: [{ q: "In welke stad werd David eerst koning over Juda?", a: ["Hebron", "Jeruzalem", "Bethlehem"], why: "2 Samuël 2:1–4" },
    { q: "Wie maakte Isboseth koning over Israël?", a: ["Abner", "Joab", "Samuël"], why: "2 Samuël 2:8–9" },
    { q: "Hoe oud was David toen hij koning werd?", a: ["Dertig jaar", "Twintig jaar", "Veertig jaar"], why: "2 Samuël 5:4" },
    { q: "Welke burcht nam David in Jeruzalem in?", a: ["De burcht Sion", "De burcht van Hazor", "De burcht van Gath"], why: "2 Samuël 5:7" }],
  cross: [["Psalm 2:6", "‘Ik toch heb Mijn Koning gezalfd over Sion, den berg Mijner heiligheid.’"],
    ["1 Kronieken 11:1–3", "Hetzelfde verhaal: heel Israël komt naar Hebron en zalft David tot koning."]],
  tl: [-1010, -1003], tijd: "ca. 1010–1003 v.Chr.",
  tijdNoot: "Reconstructie: David regeerde zeven jaar en zes maanden in Hebron en daarna in Jeruzalem (2 Samuël 5:5). De jaartallen volgen uit terugrekenen vanaf het vierde jaar van Salomo (ca. 966 v.Chr., 1 Koningen 6:1) in de gangbare chronologie; andere schema’s verschillen enkele jaren." },

{ nr: 57, t: "De ark naar Jeruzalem; Gods belofte aan David", ref: "2 Samuël 6–7", sectie: "koningen",
  stappen: ["2samuel:david:4", "2samuel:david:5"],
  vorm: "route",
  uitleg: "David wil de ark van God naar Jeruzalem halen. Ze zetten de ark op een nieuwe wagen en halen hem uit het huis van Abinadab. Als de runderen struikelen, steekt Uza zijn hand uit naar de ark, en God slaat hem; hij sterft bij de ark. David is bang en laat de ark drie maanden in het huis van Obed-Edom staan. De HEERE zegent dat huis. Daarna haalt David de ark met vreugde naar zijn stad, en hij danst met alle macht voor de HEERE. Later wil David een huis bouwen voor de ark. Maar God zegt door de profeet Nathan: Ik zal ú een huis maken. Uw zoon zal een huis voor Mijn Naam bouwen, en uw koninkrijk zal tot in eeuwigheid bestendig zijn.",
  betekenis: "De eerste keer ging het mis, omdat de ark niet gedragen werd zoals God had geboden (1 Kronieken 15:13–15). Gods belofte aan David wees ver vooruit: de engel zegt over de Heere Jezus dat God Hem ‘den troon van Zijn vader David’ zal geven, en ‘Zijns Koninkrijks zal geen einde zijn’ (Lukas 1:32–33).",
  wie: ["David", "Nathan", "Michal"],
  ontdek: { soort: "verbanden", titel: "De belofte aan David: hoe komt die terug?", items: [
    ["2 Samuël 7:12–13", "Uit David komt een zoon; God zal de troon van zijn koninkrijk bevestigen tot in eeuwigheid.", "Lukas 1:32–33", "God geeft de Heere Jezus de troon van Zijn vader David; aan Zijn Koninkrijk komt geen einde."],
    ["2 Samuël 7:14", "‘Ik zal hem zijn tot een Vader, en hij zal Mij zijn tot een zoon.’", "Hebreeën 1:5", "De Hebreeënbrief zegt dat God dit van Zijn Zoon zegt, en van geen engel."],
    ["2 Samuël 7:16", "Davids huis en koninkrijk blijven tot in eeuwigheid.", "Handelingen 2:30–31", "Petrus zegt dat David wist dat God uit zijn nakomelingen de Christus zou verwekken."]] },
  quiz: [{ q: "Waarop vervoerden ze de ark de eerste keer?", a: ["Op een nieuwe wagen", "Op de schouders van de Levieten", "Op een kameel"], why: "2 Samuël 6:3" },
    { q: "Waarom stierf Uza?", a: ["Hij strekte zijn hand uit naar de ark en hield die vast", "Hij viel van de wagen", "Hij werd door een rund getrapt"], why: "2 Samuël 6:6–7" },
    { q: "Hoe lang bleef de ark bij Obed-Edom?", a: ["Drie maanden", "Drie dagen", "Drie jaar"], why: "2 Samuël 6:11" },
    { q: "Door welke profeet sprak God tot David over het huis?", a: ["Nathan", "Gad", "Samuël"], why: "2 Samuël 7:4–5" }],
  cross: [["Lukas 1:32–33", "‘God, de Heere, zal Hem den troon van Zijn vader David geven … en Zijns Koninkrijks zal geen einde zijn.’"],
    ["Psalm 132:11", "‘De HEERE heeft David de waarheid gezworen … Van de vrucht uws buiks zal Ik op uw troon zetten.’"],
    ["1 Kronieken 15:13–15", "De tweede keer droegen de Levieten de ark op hun schouders, zoals Mozes geboden had."]],
  tl: [-1003, -990], tijd: "ca. 1003–990 v.Chr. (onzeker)",
  tijdNoot: "Reconstructie, onzeker: na de verovering van Jeruzalem, kort nadat David koning over heel Israël werd (ca. 1003 v.Chr. in de gangbare chronologie). Het precieze jaar staat niet in de Bijbel." },

{ nr: 58, t: "David en Bathseba", ref: "2 Samuël 11–12", sectie: "koningen",
  stappen: ["2samuel:david:7"],
  vorm: "plek",
  uitleg: "Terwijl het leger van Israël de stad Rabba belegert, blijft David in Jeruzalem. Vanaf het dak van zijn paleis ziet hij Bathseba, de vrouw van Uria. Hij laat haar halen en doet overspel met haar. Als zij zwanger blijkt, probeert David het te verbergen. Wanneer dat niet lukt, schrijft hij Joab een brief: zet Uria vooraan in de zwaarste strijd. Uria sneuvelt, en David trouwt met Bathseba. ‘Deze zaak, die David gedaan had, was kwaad in de ogen des HEEREN.’ God stuurt de profeet Nathan. Die vertelt over een rijke man die het enige ooilam (een vrouwtjesschaap) van een arme man afpakt. David wordt woedend, en Nathan zegt: ‘Gij zijt die man!’ David belijdt: ‘Ik heb gezondigd tegen den HEERE!’ God neemt zijn zonde weg, maar het kind dat geboren is, sterft.",
  betekenis: "Ook een koning naar Gods hart viel diep in zonde. David verborg het niet langer, maar beleed het, en God vergaf hem (2 Samuël 12:13). Zijn gebed staat in Psalm 51: ‘Was mij wel van mijn ongerechtigheid, en reinig mij van mijn zonde.’",
  wie: ["David", "Bathseba", "Uria", "Nathan", "Joab"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["De ark, en Israël, en Juda blijven in de tenten", "Uria", ["Joab", "Nathan"]],
    ["De man, die dat gedaan heeft, is een kind des doods!", "David", ["Nathan", "Joab"]],
    ["Gij zijt die man!", "Nathan", ["Joab", "Uria"]],
    ["Ik heb gezondigd tegen den HEERE!", "David", ["Uria", "Joab"]]] },
  quiz: [{ q: "Welke stad belegerde het leger terwijl David in Jeruzalem bleef?", a: ["Rabba, de stad van de Ammonieten", "Gath, de stad van Goliath", "Jericho, de oude stad bij de Jordaan"], why: "2 Samuël 11:1" },
    { q: "Hoe zorgde David ervoor dat Uria sneuvelde?", a: ["Hij schreef Joab dat Uria vooraan moest staan", "Hij stuurde hem alleen de woestijn in", "Hij liet hem gevangen zetten"], why: "2 Samuël 11:14–15" },
    { q: "Wat pakte de rijke man in het verhaal van Nathan af?", a: ["Het enige ooilam van de arme man", "Het huis van de arme man", "De akker van de arme man"], why: "2 Samuël 12:4" },
    { q: "Welke naam gaf de HEERE via Nathan aan Salomo?", a: ["Jedid-Jah", "Ikabod", "Eben-Haëzer"], why: "2 Samuël 12:25" }],
  cross: [["Psalm 51:3–4", "‘Wees mij genadig, o God! … Was mij wel van mijn ongerechtigheid.’"],
    ["Psalm 32:5", "‘Ik zeide: Ik zal belijdenis van mijn overtredingen doen voor den HEERE; en Gij vergaaft de ongerechtigheid mijner zonde.’"],
    ["Mattheüs 1:6", "Ook ‘degene, die Uria’s vrouw was geweest’ staat in het geslachtsregister van de Heere Jezus."]],
  tl: [-1000, -990], tijd: "ca. 1000–990 v.Chr. (onzeker)",
  tijdNoot: "Reconstructie, onzeker: in Davids tijd in Jeruzalem (ca. 1003–970 v.Chr. in de gangbare chronologie), vóór de geboorte van Salomo, die ca. 970 v.Chr. als jonge man koning werd. Het precieze jaar staat niet in de Bijbel." },

{ nr: 59, t: "Absalom in opstand", ref: "2 Samuël 15–19", sectie: "koningen",
  stappen: ["2samuel:david:8", "2samuel:david:9"],
  vorm: "route",
  uitleg: "Absalom, een zoon van David, steelt het hart van de mannen van Israël door bij de poort te zeggen: was ik maar rechter in het land. In Hebron laat hij zich tot koning uitroepen. David vlucht met zijn knechten uit Jeruzalem, over de beek Kidron. Huilend, met bedekt hoofd en op blote voeten gaat hij de Olijfberg op. De ark stuurt hij terug naar de stad: als de HEERE wil, zal Hij mij terugbrengen. Bij Bahurim vervloekt Simeï David en gooit hij met stenen, maar David laat hem begaan. In het woud van Efraïm wordt het leger van Absalom verslagen. Absalom blijft met zijn hoofd vastzitten in een grote eik. David had gevraagd zacht met hem te handelen, maar Joab steekt drie pijlen in zijn hart, en de wapendragers van Joab doden hem. David huilt: ‘Mijn zoon Absalom … Och, dat ik, ik voor u gestorven ware!’",
  betekenis: "Wat Nathan had gezegd, kwam uit: ‘het zwaard zal van uw huis niet afwijken’ (2 Samuël 12:10). Toch vertrouwde David op God; Psalm 3 schreef hij ‘als hij vlood voor het aangezicht van zijn zoon Absalom’.",
  wie: ["David", "Absalom", "Joab", "Simeï", "Husai", "Achitofel"],
  ontdek: { soort: "volgorde", titel: "Zet de opstand van Absalom in de goede volgorde.", items: ["Absalom steelt het hart van het volk", "Absalom koning in Hebron", "David vlucht over de Kidron en de Olijfberg op", "Simeï vervloekt David", "Absalom blijft in een eik hangen", "David huilt om zijn zoon"] },
  quiz: [{ q: "Hoe stal Absalom het hart van het volk?", a: ["Hij beloofde bij de poort iedereen recht te doen", "Hij gaf iedereen goud", "Hij versloeg de Filistijnen"], why: "2 Samuël 15:4–6" },
    { q: "Wat deed David met de ark toen hij vluchtte?", a: ["Hij liet hem terugbrengen in de stad", "Hij nam hem mee", "Hij verborg hem in een grot"], why: "2 Samuël 15:25" },
    { q: "Waarin bleef Absalom hangen?", a: ["In de takken van een grote eik", "In een net", "In een doornstruik"], why: "2 Samuël 18:9" },
    { q: "Wie stak drie pijlen in het hart van Absalom?", a: ["Joab", "Abisaï", "Husai"], why: "2 Samuël 18:14" }],
  cross: [["Psalm 3:1–2", "‘Een psalm van David, als hij vlood voor het aangezicht van zijn zoon Absalom. O HEERE! hoe zijn mijn tegenpartijders vermenigvuldigd.’"],
    ["Johannes 18:1", "Eeuwen later ging ook de Heere Jezus over de beek Kedron (Kidron), in de nacht dat Hij verraden werd."]],
  tl: [-990, -975], tijd: "ca. 990–975 v.Chr. (onzeker)",
  tijdNoot: "Reconstructie, onzeker: in de tweede helft van Davids regering in Jeruzalem (ca. 1003–970 v.Chr. in de gangbare chronologie). Het getal in 2 Samuël 15:7 (‘ten einde nu van veertig jaren’) wordt door uitleggers verschillend gelezen; daarom is het precieze jaar niet te geven." },

{ nr: 60, t: "Salomo vraagt om wijsheid", ref: "1 Koningen 3; 10", sectie: "koningen",
  stappen: ["1koningen:salomo:1", "1koningen:salomo:2", "1koningen:salomo:5", "1koningen:salomo:6"],
  vorm: "plek",
  uitleg: "In Gibeon verschijnt de HEERE ’s nachts in een droom aan de jonge koning Salomo: ‘Begeer wat Ik u geven zal.’ Salomo vraagt geen lang leven en geen rijkdom, maar ‘een verstandig hart’, om het volk te richten en goed en kwaad te onderscheiden. Dat is goed in de ogen van de HEERE, en Hij geeft hem een wijs hart, en ook rijkdom en eer. Kort daarna komen twee vrouwen met één levend kind bij hem, en allebei zeggen ze dat het van haar is. Salomo laat een zwaard halen en zegt dat het levende kind in tweeën gedeeld moet worden. De echte moeder wil het kind liever afstaan dan het laten doden. Later komt de koningin van Scheba met raadsels, en Salomo kan ze allemaal uitleggen. Ze zegt: ‘de helft is mij niet aangezegd’, en ze looft de HEERE, de God van Salomo.",
  betekenis: "Salomo’s wijsheid kwam van God: het volk zag ‘dat de wijsheid Gods in hem was’ (1 Koningen 3:28). De Heere Jezus zegt over Zichzelf: ‘meer dan Salomo is hier!’ (Mattheüs 12:42).",
  wie: ["Salomo", "Koningin"],
  kw: "wijsheid",
  ontdek: { soort: "koppel", titel: "Wat hoort bij elkaar?", paren: [
    ["Gibeon", "‘Begeer wat Ik u geven zal’ (3:5)"],
    ["Een verstandig hart", "wat Salomo vroeg (3:9)"],
    ["Een zwaard", "zo ontdekte Salomo wie de echte moeder was (3:24–27)"],
    ["Raadsels", "waarmee de koningin van Scheba hem testte (10:1)"],
    ["120 talenten goud", "wat de koningin aan Salomo gaf (10:10)"]] },
  quiz: [{ q: "Wat vroeg Salomo aan God?", a: ["Een verstandig hart", "Een lang leven", "De dood van zijn vijanden"], why: "1 Koningen 3:9" },
    { q: "Wat gaf God hem ook, al had hij het niet gevraagd?", a: ["Rijkdom en eer", "Een nieuw land", "Twaalf zonen"], why: "1 Koningen 3:13" },
    { q: "Hoe wist Salomo wie de echte moeder was?", a: ["Zij wilde het kind niet laten doden", "Zij had het mooiste kleed aan", "Zij huilde het hardst"], why: "1 Koningen 3:26–27" },
    { q: "Waarmee kwam de koningin van Scheba Salomo testen?", a: ["Met raadsels", "Met een uitdaging tot een tweegevecht", "Met een brief vol beschuldigingen"], why: "1 Koningen 10:1" }],
  cross: [["Mattheüs 12:42", "‘De koningin van het zuiden … is gekomen van de einden der aarde, om te horen de wijsheid van Salomo; en ziet, meer dan Salomo is hier!’"],
    ["Jakobus 1:5", "‘Indien iemand van u wijsheid ontbreekt, dat hij ze van God begere.’"],
    ["Spreuken 9:10", "‘De vreze des HEEREN is het beginsel der wijsheid.’"]],
  tl: [-970, -950], tijd: "ca. 970–950 v.Chr.",
  tijdNoot: "Reconstructie: de droom in Gibeon aan het begin van Salomo’s regering (ca. 970 v.Chr.); het bezoek van de koningin van Scheba na de bouw van de tempel en het paleis (1 Koningen 10:4–5). Salomo regeerde veertig jaar (1 Koningen 11:42); de jaartallen volgen de gangbare chronologie." },

{ nr: 61, t: "Salomo bouwt de tempel", ref: "1 Koningen 5–9", sectie: "koningen",
  stappen: ["1koningen:salomo:3", "1koningen:salomo:4"],
  vorm: "plek",
  uitleg: "Salomo wil een huis bouwen voor de Naam van de HEERE, zoals God tegen David had gezegd. Koning Hiram van Tyrus levert cederhout en dennenhout uit de Libanon. In het vierhonderdtachtigste jaar na de uittocht uit Egypte begint de bouw. Zeven jaar later is het huis klaar. Bij het bouwen hoort men geen hamer of bijl, want de stenen worden al klaar aangevoerd. Van binnen is alles met goud bekleed. De priesters brengen de ark in het heilige der heiligen, en een wolk vult het huis: de heerlijkheid van de HEERE. Salomo bidt: ‘de hemelen, ja, de hemel der hemelen zouden U niet begrijpen, hoeveel te min dit huis.’ Daarna verschijnt God hem opnieuw. Hij waarschuwt: als jullie andere goden gaan dienen, zal Ik dit huis wegwerpen.",
  betekenis: "God kwam echt wonen in de tempel (1 Koningen 8:10–11), maar Salomo wist dat de hemel Hem niet kan bevatten (1 Koningen 8:27). De Heere Jezus noemt later Zijn eigen lichaam de tempel: ‘Breekt dezen tempel, en in drie dagen zal Ik denzelven oprichten’ (Johannes 2:19–21).",
  wie: ["Salomo", "Hiram", "Priesters"],
  kw: "tempel",
  ontdek: { soort: "onthul", titel: "Tik op een getal: wat weet je van de tempel?", items: [
    ["480", "Zoveel jaar na de uittocht uit Egypte begon de bouw (6:1)."],
    ["60 el", "De tempel was zestig el lang, twintig breed en dertig hoog (6:2)."],
    ["10 el", "Zo hoog was elk van de twee cherubs in het heilige der heiligen (6:23)."],
    ["7 jaar", "Zo lang werd er aan de tempel gebouwd (6:38)."],
    ["2 tafelen", "In de ark lag niets anders dan de twee stenen tafelen van Mozes (8:9)."]] },
  quiz: [{ q: "Welk hout leverde Hiram voor de tempel?", a: ["Cederhout en dennenhout", "Eikenhout", "Palmhout"], why: "1 Koningen 5:10" },
    { q: "Wat hoorde men niet bij het bouwen van de tempel?", a: ["Hamer, bijl of ander ijzeren gereedschap", "Het blazen op bazuinen", "Het zingen van de Levieten"], why: "1 Koningen 6:7" },
    { q: "Wat lag er in de ark toen hij in de tempel kwam?", a: ["Alleen de twee stenen tafelen", "Goud en zilver", "Het zwaard van Goliath"], why: "1 Koningen 8:9" },
    { q: "Wat vulde het huis toen de priesters uit het heilige kwamen?", a: ["Een wolk: de heerlijkheid van de HEERE", "Een sterke wind van de woestijn", "Water uit de rots"], why: "1 Koningen 8:10–11" }],
  cross: [["Johannes 2:19–21", "De Heere Jezus ‘zeide dit van den tempel Zijns lichaams’."],
    ["1 Korinthe 3:16", "‘Weet gij niet, dat gij Gods tempel zijt, en de Geest Gods in ulieden woont?’"],
    ["2 Samuël 7:13", "God had tegen David gezegd: uw zoon ‘zal Mijn Naam een huis bouwen’."]],
  tl: [-966, -959], tijd: "ca. 966–959 v.Chr.",
  tijdNoot: "Reconstructie: de bouw begon in het vierde jaar van Salomo, 480 jaar na de uittocht (1 Koningen 6:1), en was klaar in het elfde jaar (6:38). In de gangbare chronologie (Thiele e.a.) is dat ca. 966–959 v.Chr.; andere schema’s verschillen enkele jaren." },

{ nr: 62, t: "Salomo’s afval en het gescheurde rijk", ref: "1 Koningen 11–12", sectie: "koningen",
  stappen: ["1koningen:salomo:7", "1koningen:salomo:8"],
  vorm: "plek",
  uitleg: "Salomo heeft veel vreemde vrouwen lief. Ze komen uit volken waarvan de HEERE had gezegd: ga niet met hen om, want ze zullen je hart naar hun goden trekken. Als Salomo oud is, gebeurt dat ook, en hij bouwt hoogten voor Kamos en Molech. De HEERE wordt toornig: Ik zal het koninkrijk van u afscheuren, maar niet in uw dagen, om David; één stam zal Ik uw zoon geven. De profeet Ahia scheurt zijn nieuwe kleed in twaalf stukken en zegt tegen Jerobeam: ‘Neem u tien stukken.’ Na de dood van Salomo vraagt het volk aan Rehabeam: maak ons juk lichter. Rehabeam luistert niet naar de oude raadslieden, maar naar de jonge mannen, en hij antwoordt hard. Dan maken tien stammen Jerobeam koning; alleen Juda blijft bij het huis van David. Jerobeam maakt twee gouden kalveren, in Bethel en in Dan, ‘en deze zaak werd tot zonde’.",
  betekenis: "Het gescheurde rijk was Gods straf, ‘daarom dat zij Mij verlaten’ hebben (1 Koningen 11:33). Toch bleef God trouw aan Zijn belofte aan David: één stam bleef voor zijn zoon, ‘om Mijns knechts Davids wil’ (1 Koningen 11:13).",
  wie: ["Salomo", "Ahia", "Jerobeam", "Rehabeam"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Neem u tien stukken", "Ahia", ["Salomo", "Rehabeam"]],
    ["Mijn vader heeft u met geselen gekastijd, maar ik zal u met schorpioenen kastijden", "Rehabeam", ["Salomo", "Jerobeam"]],
    ["Wat deel hebben wij aan David? … naar uw tenten, o Israël!", "Het volk van Israël", ["Rehabeam", "Ahia"]],
    ["Zie uw goden, o Israël, die u uit Egypteland opgebracht hebben", "Jerobeam", ["Rehabeam", "Ahia"]]] },
  quiz: [{ q: "In hoeveel stukken scheurde Ahia zijn nieuwe kleed?", a: ["Twaalf", "Tien", "Twee"], why: "1 Koningen 11:30" },
    { q: "Naar wie luisterde Rehabeam?", a: ["Naar de jonge mannen die met hem opgegroeid waren", "Naar de oude raadslieden van Salomo", "Naar de profeet Ahia"], why: "1 Koningen 12:8" },
    { q: "Waar zette Jerobeam de gouden kalveren neer?", a: ["In Bethel en Dan", "In Jeruzalem en Hebron", "In Silo en Gilgal"], why: "1 Koningen 12:29" },
    { q: "Hoe lang regeerde Salomo over heel Israël?", a: ["Veertig jaar", "Zeven jaar", "Twintig jaar"], why: "1 Koningen 11:42" }],
  cross: [["Deuteronomium 17:17", "Een koning mocht niet veel vrouwen nemen, ‘opdat zijn hart niet afwijke’."],
    ["Nehemia 13:26", "‘Ook hem deden de vreemde vrouwen zondigen.’"],
    ["2 Kronieken 10:15", "‘Deze omwending was van God’: zo kwam uit wat Ahia gezegd had."]],
  tl: [-940, -930], tijd: "ca. 940–930 v.Chr.",
  tijdNoot: "Reconstructie: in de ouderdom van Salomo (1 Koningen 11:4) en direct na zijn dood. De scheuring van het rijk valt in de gangbare chronologie (Thiele e.a.) ca. 931/930 v.Chr.; andere schema’s verschillen enkele jaren." },

{ nr: 63, t: "Elia en de profeten van Baäl", ref: "1 Koningen 16–18", sectie: "profeten",
  stappen: ["1koningen:elia:0", "1koningen:elia:1", "1koningen:elia:2", "1koningen:elia:3", "1koningen:elia:4"],
  vorm: "route",
  uitleg: "Koning Achab trouwt met Izebel, dient de Baäl en bouwt een altaar voor Baäl in Samaria. Elia zegt tegen Achab dat er geen dauw of regen zal komen, tenzij op zijn woord. God laat Elia door raven voeden bij de beek Krith. Daarna zorgt een weduwe in Zarfath voor hem, en bij haar raken het meel en de olie niet op. In het derde jaar roept Elia heel Israël en de vierhonderdvijftig profeten van Baäl bij elkaar op de berg Karmel. ‘Hoe lang hinkt gij op twee gedachten? Zo de HEERE God is, volgt Hem na, en zo het Baäl is, volgt hem na!’ De Baälprofeten roepen van de morgen tot de middag, maar er komt geen antwoord. Elia laat het offer drie keer overgieten met water en bidt. Het vuur van de HEERE valt en verteert alles, en het volk roept: ‘De HEERE is God, de HEERE is God!’ Daarna komt er een grote regen.",
  betekenis: "Op de Karmel liet God zien dat Hij alleen God is, en Baäl niets. Elia bad: ‘dat het heden bekend worde, dat Gij God in Israël zijt’ (1 Koningen 18:36). Jakobus noemt hem ‘een mens van gelijke bewegingen als wij’, wiens gebed God verhoorde (Jakobus 5:17–18).",
  wie: ["Elia", "Achab", "Izebel", "Obadja", "Weduwe"],
  ontdek: { soort: "kaart", vraag: "Tik op de berg Karmel, waar het vuur van de HEERE viel.", id: "karmel", v: "kanaan" },
  quiz: [{ q: "Wie brachten Elia brood en vlees bij de beek Krith?", a: ["Raven", "Engelen", "Obadja"], why: "1 Koningen 17:6" },
    { q: "Wat raakte niet op bij de weduwe in Zarfath?", a: ["Het meel en de olie", "Het water", "Het hout"], why: "1 Koningen 17:16" },
    { q: "Hoeveel profeten van Baäl waren er op de Karmel?", a: ["450", "400", "12"], why: "1 Koningen 18:22" },
    { q: "Hoeveel keer liet Elia water over het offer gieten?", a: ["Drie keer", "Eén keer", "Zeven keer"], why: "1 Koningen 18:34" },
    { q: "Wat riep het volk toen het vuur viel?", a: ["De HEERE is God, de HEERE is God!", "Leve koning Achab!", "O Baäl, antwoord ons!"], why: "1 Koningen 18:39" }],
  cross: [["Jakobus 5:17–18", "Elia bad, en het regende drie jaar en zes maanden niet; hij bad opnieuw, en de hemel gaf regen."],
    ["Lukas 4:25–26", "De Heere Jezus noemt de weduwe van Zarfath (Sarepta): naar haar werd Elia gestuurd."],
    ["Romeinen 11:2–4", "God had Zich zevenduizend mannen overgelaten die de knie niet voor Baäl gebogen hadden."]],
  tl: [-874, -853], tijd: "ca. 874–853 v.Chr. (tijd van Achab)",
  tijdNoot: "Reconstructie: Achab werd koning in het 38e jaar van Asa en regeerde 22 jaar (1 Koningen 16:29), in de gangbare chronologie (Thiele) ca. 874–853 v.Chr. In welke jaren van Achab de droogte viel, staat niet in de Bijbel; Jakobus 5:17 noemt drie jaar en zes maanden." },

{ nr: 64, t: "Naäman wordt genezen", ref: "2 Koningen 5", sectie: "profeten",
  stappen: ["2koningen:elisa:4"],
  vorm: "route",
  uitleg: "Naäman is de legeroverste van de koning van Syrië, een groot en dapper man, maar hij is melaats. Een klein meisje, dat als gevangene uit Israël is meegenomen, dient zijn vrouw. Zij zegt: was mijn heer maar bij de profeet in Samaria, die zou hem van zijn melaatsheid genezen. Naäman reist met een brief, veel zilver en goud en met paarden en wagens naar Israël. Zo komt hij bij het huis van Elisa. Elisa laat zeggen: ‘Ga heen en was u zevenmaal in de Jordaan.’ Naäman wordt eerst boos, maar zijn knechten overtuigen hem. Na de zevende keer is zijn huid als die van een kleine jongen, en hij is rein. Hij keert terug en zegt: ‘nu weet ik, dat er geen God is op de ganse aarde, dan in Israël!’ Gehazi, de knecht van Elisa, loopt Naäman achterna om toch zilver te krijgen. Hij liegt, en hij wordt zelf melaats.",
  betekenis: "Een klein meisje vertelde, ver van huis, waar hulp te vinden was, en zo leerde Naäman de levende God kennen (2 Koningen 5:3, 15). De Heere Jezus noemt Naäman de Syriër als iemand uit een ander volk aan wie God genade bewees (Lukas 4:27).",
  wie: ["Naäman", "Meisje", "Elisa", "Gehazi"],
  kw: "getuigen",
  ontdek: { soort: "volgorde", titel: "Zet het verhaal van Naäman in de goede volgorde.", items: ["Het meisje vertelt over de profeet in Samaria", "Naäman brengt een brief naar de koning van Israël", "Naäman stopt voor het huis van Elisa", "Zeven keer in de Jordaan", "Naäman komt terug en belijdt de God van Israël", "Gehazi wordt melaats"] },
  quiz: [{ q: "Wie vertelde dat de profeet in Samaria Naäman kon genezen?", a: ["Een klein meisje uit Israël", "De koning van Syrië", "Gehazi"], why: "2 Koningen 5:2–3" },
    { q: "Hoeveel keer moest Naäman zich wassen in de Jordaan?", a: ["Zeven keer", "Drie keer", "Eén keer"], why: "2 Koningen 5:10" },
    { q: "Welke rivieren van Damascus vond Naäman beter?", a: ["Abana en Farpar", "Nijl en Eufraat", "Jabbok en Arnon"], why: "2 Koningen 5:12" },
    { q: "Wat gebeurde er met Gehazi?", a: ["Hij werd melaats, wit als sneeuw", "Hij werd rijk", "Hij werd profeet in Samaria"], why: "2 Koningen 5:27" }],
  cross: [["Lukas 4:27", "‘Er waren vele melaatsen in Israël, ten tijde van den profeet Elisa; en geen van hen werd gereinigd, dan Naäman, de Syriër.’"],
    ["Psalm 96:3", "‘Vertelt onder de heidenen Zijn eer, onder alle volken Zijn wonderen.’"],
    ["Handelingen 1:8", "De Heere Jezus: ‘gij zult Mijn getuigen zijn … tot aan het uiterste der aarde.’"]],
  tl: [-850, -795], tijd: "ca. 850–795 v.Chr. (tijd van Elisa)",
  tijdNoot: "Reconstructie: in de tijd van Elisa, die Elia opvolgde kort na de dood van Achab en Ahazia en stierf in de tijd van Joas van Israël (2 Koningen 13:14), in de gangbare chronologie (Thiele) ca. 850–795 v.Chr. De koning van Israël in 2 Koningen 5 wordt niet bij naam genoemd; daarom is het jaar niet preciezer te geven." }
);

Object.assign(BR.kernwoorden, {
  offeren: { n: "Offeren",
    uitleg: "Offeren is iets aan God geven. In Israël was dat vaak een dier zonder gebrek, dat geslacht en op het altaar verbrand werd. Dat mocht niet op je eigen manier: God zei Zelf welke offers, door wie en waar (Leviticus 1:2–4; 10:1–2). God gaf het bloed op het altaar ‘om over uw zielen verzoening te doen’ (Leviticus 17:11). Die offers moesten steeds opnieuw gebracht worden, want het bloed van stieren en bokken kan de zonden niet wegnemen; ze wezen vooruit naar het ene offer van de Heere Jezus (Hebreeën 10:4, 10).",
    refs: [["Genesis 22:13", "Abraham offert een ram ‘in zijns zoons plaats’."],
      ["Leviticus 17:11", "‘Het is het bloed, dat voor de ziel verzoening zal doen.’"],
      ["Hebreeën 10:10–14", "Door één offer heeft de Heere Jezus voor altijd volmaakt wie geheiligd worden."],
      ["Romeinen 12:1", "Gelovigen geven hun leven aan God als ‘een levende, heilige en Gode welbehagelijke offerande’."]] },
  leven: { n: "Leven",
    uitleg: "Leven komt van God: Hij blies de mens ‘den adem des levens’ in (Genesis 2:7). Door de zonde kwam de dood in de wereld (Romeinen 5:12). In de woestijn bleef iedereen in leven die naar de koperen slang keek, omdat God dat beloofd had (Numeri 21:8–9). De Heere Jezus zegt: ‘Ik ben de Opstanding en het Leven’ (Johannes 11:25). Wie in Hem gelooft, heeft het eeuwige leven (Johannes 3:16).",
    refs: [["Genesis 2:7", "God blies de mens de adem des levens in."],
      ["Deuteronomium 30:19", "Mozes: ‘Kiest dan het leven, opdat gij levet.’"],
      ["Johannes 3:14–16", "Zoals de koperen slang verhoogd werd, zo de Zoon des mensen: wie in Hem gelooft, heeft het eeuwige leven."],
      ["Johannes 11:25", "‘Ik ben de Opstanding en het Leven.’"]] },
  volharding: { n: "Volharding",
    uitleg: "Volharden is blijven doen wat God zegt, ook als je nog niets ziet gebeuren. Bij Jericho liep het volk dag na dag om de stad zonder dat de muren bewogen, tot God deed wat Hij beloofd had (Jozua 6; Hebreeën 11:30). De Heere Jezus zegt: ‘wie volharden zal tot het einde, die zal zalig worden’ (Mattheüs 24:13). Volharding komt niet uit eigen kracht: God maakt af wat Hij begonnen is (Filippenzen 1:6).",
    refs: [["Hebreeën 11:30", "De muren van Jericho vielen door het geloof, na zeven dagen rondgaan."],
      ["Numeri 14:24", "Kaleb ‘heeft volhard’ de HEERE na te volgen."],
      ["Lukas 18:1", "De Heere Jezus leert dat men altijd moet bidden ‘en niet vertragen’."],
      ["Filippenzen 1:6", "God zal het goede werk dat Hij begonnen is, voleindigen."]] },
  god: { n: "God",
    uitleg: "De Bijbel begint met God: ‘In den beginne schiep God den hemel en de aarde’ (Genesis 1:1). Er is maar één God: ‘de HEERE, onze God, is een enig HEERE’ (Deuteronomium 6:4). Hij is heilig en rechtvaardig, en ook ‘barmhartig en genadig’ (Exodus 34:6). In het boek Ruth zie je dat Hij ook in gewone dagen voor Zijn volk zorgt: Hij geeft brood, een losser en een kind (Ruth 1:6; 4:13–14). Het duidelijkst heeft God Zich laten kennen door Zijn Zoon, de Heere Jezus (Johannes 1:18).",
    refs: [["Genesis 1:1", "God schiep de hemel en de aarde."],
      ["Deuteronomium 6:4", "‘Hoor, Israël! de HEERE, onze God, is een enig HEERE!’"],
      ["Exodus 34:6", "‘HEERE, HEERE, God, barmhartig en genadig, lankmoedig en groot van weldadigheid en waarheid.’"],
      ["Johannes 1:18", "De eniggeboren Zoon heeft God aan ons verklaard."]] },
  eeuwigheid: { n: "Eeuwigheid",
    uitleg: "Eeuwigheid is tijd zonder einde. Alleen God is altijd geweest: ‘van eeuwigheid tot eeuwigheid zijt Gij God’ (Psalm 90:2). Een mens leeft maar kort op aarde, en ‘het is den mensen gezet, eenmaal te sterven, en daarna het oordeel’ (Hebreeën 9:27). De Heere Jezus spreekt over ‘de eeuwige pijn’ en ‘het eeuwige leven’ (Mattheüs 25:46). Wie in de Zoon gelooft, heeft het eeuwige leven (Johannes 3:36).",
    refs: [["Psalm 90:2", "God is van eeuwigheid tot eeuwigheid."],
      ["Hebreeën 9:27", "Eenmaal sterven, en daarna het oordeel."],
      ["Mattheüs 25:46", "Twee wegen die voor altijd duren."],
      ["2 Korinthe 4:18", "‘De dingen, die men ziet, zijn tijdelijk, maar de dingen, die men niet ziet, zijn eeuwig.’"]] },
  wijsheid: { n: "Wijsheid",
    uitleg: "Wijsheid is meer dan veel weten: het is weten hoe je moet leven zoals God het wil. ‘De vreze des HEEREN is het beginsel der wijsheid’ (Spreuken 9:10). Salomo kreeg zijn wijsheid van God, omdat hij erom vroeg (1 Koningen 3:9–12). Wie wijsheid mist, mag erom bidden (Jakobus 1:5). In de Heere Jezus ‘zijn al de schatten der wijsheid en der kennis verborgen’ (Kolossenzen 2:3).",
    refs: [["Spreuken 9:10", "De vreze des HEEREN is het beginsel der wijsheid."],
      ["1 Koningen 4:29", "God gaf Salomo wijsheid en zeer veel verstand."],
      ["Jakobus 1:5", "Bid God om wijsheid; Hij geeft graag."],
      ["Kolossenzen 2:3", "Alle schatten van wijsheid en kennis zijn in Christus."]] },
  tempel: { n: "Tempel",
    uitleg: "De tempel was het huis van God in Jeruzalem, gebouwd door Salomo. Daar stond de ark, daar werden de offers gebracht, en daar vulde de heerlijkheid van de HEERE het huis (1 Koningen 8:10–11). Toch wist Salomo dat zelfs de hemel God niet kan bevatten (1 Koningen 8:27). De Heere Jezus noemde Zijn lichaam de tempel (Johannes 2:19–21). Paulus schrijft dat de gemeente nu Gods tempel is, waarin de Geest van God woont (1 Korinthe 3:16).",
    refs: [["1 Koningen 8:10–13", "De wolk van de heerlijkheid van de HEERE vult het huis."],
      ["Johannes 2:19–21", "De Heere Jezus spreekt over de tempel van Zijn lichaam."],
      ["1 Korinthe 3:16", "De gemeente is Gods tempel."],
      ["Openbaring 21:22", "In het nieuwe Jeruzalem is geen tempel: God en het Lam zijn de Tempel."]] },
  getuigen: { n: "Getuigen",
    uitleg: "Een getuige vertelt wat hij zelf gezien of gehoord heeft, en dat moet waar zijn: ‘Gij zult geen valse getuigenis spreken’ (Exodus 20:16). Het meisje bij Naäman vertelde wat ze wist over de profeet van de HEERE, en zo leerde Naäman God kennen (2 Koningen 5:3, 15). God zegt tegen Israël: ‘Gijlieden zijt Mijn getuigen’ (Jesaja 43:10). De Heere Jezus zond Zijn discipelen uit om Zijn getuigen te zijn ‘tot aan het uiterste der aarde’ (Handelingen 1:8).",
    refs: [["Exodus 20:16", "Het negende gebod: geen valse getuigenis."],
      ["2 Koningen 5:3", "Een gevangen meisje wijst haar meesteres op de profeet in Samaria."],
      ["Jesaja 43:10", "‘Gijlieden zijt Mijn getuigen, spreekt de HEERE.’"],
      ["Handelingen 1:8", "‘Gij zult Mijn getuigen zijn … tot aan het uiterste der aarde.’"]] },
});
